INSERT INTO `wp_options` VALUES (1720,'wpcode_snippets','a:1:{s:16:\"site_wide_footer\";a:2:{i:0;a:14:{s:2:\"id\";i:248;s:5:\"title\";s:11:\"Mouse Click\";s:4:\"code\";s:1111:\"document.addEventListener(\"DOMContentLoaded\", function() {\r\n    // Event delegation: Listen on the body, capture clicks for our buttons\r\n    document.body.addEventListener(\'mousedown\', function(e) {\r\n        const btn = e.target.closest(\'.lycos-hero-btn-solid, .lycos-hero-btn-outline\');\r\n        if (btn) {\r\n            const link = btn.querySelector(\'a\') ? btn.querySelector(\'a\').getAttribute(\'href\') : btn.getAttribute(\'href\');\r\n            if (link && link !== \'#\') {\r\n                window.location.href = link;\r\n            }\r\n        }\r\n    }, true); // The \'true\' is critical: it intercepts the click during capture\r\n\r\n    // Manual hover simulation\r\n    document.body.addEventListener(\'mouseover\', function(e) {\r\n        const btn = e.target.closest(\'.lycos-hero-btn-solid, .lycos-hero-btn-outline\');\r\n        if (btn) btn.classList.add(\'js-hover-active\');\r\n    }, true);\r\n    document.body.addEventListener(\'mouseout\', function(e) {\r\n        const btn = e.target.closest(\'.lycos-hero-btn-solid, .lycos-hero-btn-outline\');\r\n        if (btn) btn.classList.remove(\'js-hover-active\');\r\n    }, true);\r\n});\";s:9:\"code_type\";s:2:\"js\";s:8:\"location\";s:16:\"site_wide_footer\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2026-06-18 14:17:22\";}i:1;a:14:{s:2:\"id\";i:219;s:5:\"title\";s:14:\"Node animation\";s:4:\"code\";s:1544:\"document.addEventListener(\'DOMContentLoaded\', function() {\r\n    const svg = document.getElementById(\'network-svg\');\r\n    if (!svg) return;\r\n\r\n    const linesGroup = document.getElementById(\'lines\');\r\n    const nodesGroup = document.getElementById(\'nodes\');\r\n    const aiNode = document.getElementById(\'ai-node\');\r\n    const count = 15;\r\n    const nodes = Array.from({ length: count }, () => ({\r\n        x: Math.random() * 500,\r\n        y: Math.random() * 500,\r\n        vx: (Math.random() - 0.5) * 0.4,\r\n        vy: (Math.random() - 0.5) * 0.4\r\n    }));\r\n\r\n    function render() {\r\n        linesGroup.innerHTML = \'\';\r\n        nodesGroup.innerHTML = \'\';\r\n        \r\n        nodes.forEach((n, i) => {\r\n            n.x += n.vx; n.y += n.vy;\r\n            if (n.x < 0 || n.x > 500) n.vx *= -1;\r\n            if (n.y < 0 || n.y > 500) n.vy *= -1;\r\n\r\n            const c = document.createElementNS(\"http://www.w3.org/2000/svg\", \"circle\");\r\n            c.setAttribute(\"cx\", n.x); c.setAttribute(\"cy\", n.y); c.setAttribute(\"r\", 3);\r\n            nodesGroup.appendChild(c);\r\n\r\n            for (let j = i + 1; j < i + 3; j++) {\r\n                const target = nodes[j % count];\r\n                const l = document.createElementNS(\"http://www.w3.org/2000/svg\", \"line\");\r\n                l.setAttribute(\"x1\", n.x); l.setAttribute(\"y1\", n.y);\r\n                l.setAttribute(\"x2\", target.x); l.setAttribute(\"y2\", target.y);\r\n                linesGroup.appendChild(l);\r\n            }\r\n        });\r\n        requestAnimationFrame(render);\r\n    }\r\n    render();\r\n});\";s:9:\"code_type\";s:2:\"js\";s:8:\"location\";s:16:\"site_wide_footer\";s:11:\"auto_insert\";i:1;s:13:\"insert_number\";i:1;s:9:\"use_rules\";b:0;s:5:\"rules\";a:0:{}s:8:\"priority\";i:10;s:14:\"location_extra\";s:0:\"\";s:20:\"shortcode_attributes\";a:0:{}s:13:\"compiled_code\";s:0:\"\";s:8:\"modified\";s:19:\"2026-06-18 14:01:30\";}}}','auto');
