INSERT INTO `wp_posts` VALUES (95,1,'2026-06-16 07:37:49','2026-06-16 07:37:49','<!-- wp:html -->\n<style>\n/* Remove standard browser/theme constraints */\nhtml, body, #wrapper {\n    overflow-x: hidden !important;\n    overflow-y: auto !important;\n    margin: 0 !important;\n    padding: 0 !important;\n    width: 100vw;\n    height: 100vh;\n}\n\n/* Hide the page title block if Flatsome forces it */\n.page-title { \n    display: none !important; \n}\n\n/* Base Master Frame */\n.horizontal-site-wrapper {\n    position: relative;\n    width: 100vw;\n    height: 100vh;\n    overflow: hidden;\n}\n\n/* The Continuous Parallax Background Layer */\n.parallax-bg-track {\n    position: absolute;\n    top: 0;\n    left: 0;\n    height: 100vh;\n    width: 250vw; /* Wider than the viewport to create the sliding motion */\n    background-color: #112237; /* Your exact dark blue color hook */\n    background-size: cover;\n    background-position: left center;\n    background-repeat: no-repeat;\n    z-index: 1;\n    will-change: transform;\n}\n\n/* The Main Content Track Slider */\n.gsap-horizontal-track {\n    position: relative;\n    display: flex;\n    flex-wrap: nowrap;\n    width: max-content;\n    height: 100vh;\n    z-index: 2;\n}\n\n/* Desktop Viewport Panel */\n.horizontal-section {\n    width: 100vw;\n    height: 100vh;\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    box-sizing: border-box;\n    padding: 10%;\n}\n\n/* Sample styling for your content cards */\n.content-card {\n    background: rgba(17, 34, 55, 0.85); /* Slightly translucent matching blue */\n    padding: 3rem;\n    border-radius: 12px;\n    border: 1px solid rgba(255, 255, 255, 0.1);\n    max-width: 600px;\n    color: #ffffff;\n}\n</style>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n<div class=\"horizontal-site-wrapper\">\n    \n    <div class=\"parallax-bg-track\" style=\"background-image: url(\'/wp-content/uploads/2026/06/network-bg.jpg\');\"></div>\n\n    <div class=\"gsap-horizontal-track\">\n        \n        <div class=\"horizontal-section\">\n            <div class=\"content-card\" style=\"text-align: center;\">\n                <h1 style=\"font-size: 3.5rem; color: #ffffff; margin-bottom: 1rem;\">LYCOS CORE</h1>\n                <p style=\"font-size: 1.2rem; opacity: 0.8;\">Scroll down with your mouse wheel to navigate.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">Architecting Intelligence</h2>\n                <p style=\"opacity: 0.9;\">Custom AI models built to scale operational clarity across local data frameworks.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">System Solutions</h2>\n                <p style=\"opacity: 0.9;\">Designing seamless digital flows for custom web applications and business engines.</p>\n            </div>\n        </div>\n\n    </div>\n</div>\n\n<script>\ndocument.addEventListener(\"DOMContentLoaded\", function() {\n    gsap.registerPlugin(ScrollTrigger);\n    \n    let mm = gsap.matchMedia();\n\n    // Fire horizontal timeline only on Desktop devices\n    mm.add(\"(min-width: 993px)\", () => {\n        let wrapper = document.querySelector(\'.horizontal-site-wrapper\');\n        let contentTrack = document.querySelector(\'.gsap-horizontal-track\');\n        let bgTrack = document.querySelector(\'.parallax-bg-track\');\n        let sections = gsap.utils.toArray(\'.horizontal-section\');\n        let numSections = sections.length;\n\n        if (contentTrack && numSections > 0) {\n            let tl = gsap.timeline({\n                scrollTrigger: {\n                    trigger: wrapper,\n                    pin: true,\n                    scrub: 1,\n                    // Dynamic track length proportional to number of views\n                    end: () => \"+=\" + (window.innerWidth * numSections),\n                    invalidateOnRefresh: true\n                }\n            });\n\n            // Fluid horizontal transformation of panels\n            tl.to(contentTrack, {\n                x: () => -(window.innerWidth * (numSections - 1)),\n                ease: \"none\"\n            }, 0);\n\n            // Subtle 30% speed horizontal drag for the backdrop asset\n            if (bgTrack) {\n                tl.to(bgTrack, {\n                    x: () => -(window.innerWidth * (numSections - 1) * 0.3),\n                    ease: \"none\"\n                }, 0);\n            }\n        }\n    });\n});\n</script>\n<!-- /wp:html -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Home','','inherit','closed','closed','','91-revision-v1','','','2026-06-16 07:37:49','2026-06-16 07:37:49','',91,'http://lycos-core.local/?p=95',0,'revision','',0);
