on\');\n        let numSections = sections.length;\n\n        if (contentTrack &amp;&amp; numSections > 0) {\n            let tl = gsap.timeline({\n                scrollTrigger: {\n                    trigger: wrapper,\n                    pin: true,\n                    scrub: 1,\n                    // Dynamic track length proportional to number of views\n                    end: () => \"+=\" + (window.innerWidth * numSections),\n                    invalidateOnRefresh: true\n                }\n            });\n\n            // Fluid horizontal transformation of panels\n            tl.to(contentTrack, {\n                x: () => -(window.innerWidth * (numSections - 1)),\n                ease: \"none\"\n            }, 0);\n\n            // Subtle 30% speed horizontal drag for the backdrop asset\n            if (bgTrack) {\n                tl.to(bgTrack, {\n                    x: () => -(window.innerWidth * (numSections - 1) * 0.3),\n                    ease: \"none\"\n                }, 0);\n            }\n        }\n    });\n});\n&lt;/script></code></pre>\n<!-- /wp:code -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->','Home','','inherit','closed','closed','','91-revision-v1','','','2026-06-16 07:39:33','2026-06-16 07:39:33','',91,'http://lycos-core.local/?p=98',0,'revision','',0);
