>\n\n<div class=\"horizontal-site-wrapper\">\n    \n    <div class=\"parallax-bg-track\" style=\"background-image: url(\'media/Parallax.png\');\"></div>\n\n    <div class=\"gsap-horizontal-track\">\n        \n        <div class=\"horizontal-section\">\n            <div class=\"content-card\" style=\"text-align: center;\">\n                <h1 style=\"font-size: 3.5rem; color: #ffffff; margin-bottom: 1rem;\">LYCOS CORE</h1>\n                <p style=\"font-size: 1.2rem; opacity: 0.8;\">Scroll down with your mouse wheel to navigate.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">Architecting Intelligence</h2>\n                <p style=\"opacity: 0.9;\">Custom AI models built to scale operational clarity across local data frameworks.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">System Solutions</h2>\n                <p style=\"opacity: 0.9;\">Designing seamless digital flows for custom web applications and business engines.</p>\n            </div>\n        </div>\n\n    </div>\n</div>\n\n<script>\ndocument.addEventListener(\"DOMContentLoaded\", function() {\n    gsap.registerPlugin(ScrollTrigger);\n    \n    let mm = gsap.matchMedia();\n\n    // Fire horizontal timeline only on Desktop devices\n    mm.add(\"(min-width: 993px)\", () => {\n        let wrapper = document.querySelector(\'.horizontal-site-wrapper\');\n        let contentTrack = document.querySelector(\'.gsap-horizontal-track\');\n        let bgTrack = document.querySelector(\'.parallax-bg-track\');\n        let sections = gsap.utils.toArray(\'.horizontal-section\');\n        let numSections = sections.length;\n\n        if (contentTrack && numSections > 0) {\n            let tl = gsap.timeline({\n                scrollTrigger: {\n                    trigger: wrapper,\n                    pin: true,\n                    scrub: 1,\n                    // Dynamic track length proportional to number of views\n                    end: () => \"+=\" + (window.innerWidth * numSections),\n                    invalidateOnRefresh: true\n                }\n            });\n\n            // Fluid horizontal transformation of panels\n            tl.to(contentTrack, {\n                x: () => -(window.innerWidth * (numSections - 1)),\n                ease: \"none\"\n            }, 0);\n\n            // Subtle 30% speed horizontal drag for the backdrop asset\n            if (bgTrack) {\n                tl.to(bgTrack, {\n                    x: () => -(window.innerWidth * (numSections - 1) * 0.3),\n                    ease: \"none\"\n                }, 0);\n            }\n        }\n    });\n});\n</script>\n[/ux_html]\n\n<!-- /wp:flatsome/uxbuilder -->','Home','','inherit','closed','closed','','91-revision-v1','','','2026-06-16 07:42:21','2026-06-16 07:42:21','',91,'http://lycos-core.local/?p=100',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (101,1,'2026-06-16 07:52:30','2026-06-16 07:52:30','<!-- wp:flatsome/uxbuilder -->\n[ux_html]\n\n<style>\n/* Remove standard browser/theme constraints to lock the viewport */\nhtml, body, #wrapper {\n    overflow-x: hidden !important;\n    overflow-y: auto !important;\n    margin: 0 !important;\n    padding: 0 !important;\n    width: 100vw;\n    height: 100vh;\n    background-color: #112237 !important; /* Your exact dark blue background baseline */\n}\n\n/* Hide the default page title block if Flatsome injects it */\n.page-title { \n    display: none !important; \n}\n\n/* Base Master Outer Canvas Frame */\n.horizontal-site-wrapper {\n    position: relative;\n    width: 100vw;\n    height: 100vh;\n    overflow: hidden;\n}\n\n/* The Continuous Parallax Background Layer */\n.parallax-bg-track {\n    position: absolute;\n    top: 0;\n    left: 0;\n    height: 100vh;\n    width: 250vw; /* Wider than the viewport to accommodate the panning room */\n    background-color: #112237; \n    background-size: cover;\n    background-position: left center;\n    background-repeat: no-repeat;\n    z-index: 1;\n    will-change: transform;\n}\n\n/* The Main Foreground Horizontal Content Slider Track */\n.gsap-horizontal-track {\n    position: relative;\n    display: flex;\n    flex-wrap: nowrap;\n    width: max-content;\n    height: 100vh;\n    z-index: 2;\n}\n\n/* Individual Full Screen Desktop Viewport Section Panels */\n.horizontal-section {\n    width: 100vw;\n    height: 100vh;\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    box-sizing: border-box;\n    padding: 10%;\n    background: transparent !important; /* Lets the background asset show through */\n}\n\n/* Translucent content styling boxes */\n.content-card {\n    background: rgba(17, 34, 55, 0.85); /* Slightly translucent matching base blue */\n    padding: 3rem;\n    border-radius: 12px;\n    border: 1px solid rgba(255, 255, 255, 0.1);\n    max-width: 600px;\n    color: #ffffff;\n}\n</style>\n\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n\n<div class=\"horizontal-site-wrapper\">\n    \n    <div class=\"parallax-bg-track\" style=\"background-image: url(\'/media/Parallax.png\');\"></div>\n\n    <div class=\"gsap-horizontal-track\">\n        \n        <div class=\"horizontal-section\">\n            <div class=\"content-card\" style=\"text-align: center;\">\n                <h1 style=\"font-size: 3.5rem; color: #ffffff; margin-bottom: 1rem;\">LYCOS CORE</h1>\n                <p style=\"font-size: 1.2rem; opacity: 0.8;\">Scroll down with your mouse wheel to navigate horizontally.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">Architecting Intelligence</h2>\n                <p style=\"opacity: 0.9;\">Custom AI models built to scale operational clarity across local data frameworks.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">System Solutions</h2>\n                <p style=\"opacity: 0.9;\">Designing seamless digital flows for custom web applications and corporate business engines.</p>\n            </div>\n        </div>\n\n    </div>\n</div>\n\n\n<script>\nwindow.addEventListener(\"load\", function() {\n    // Graceful error trap to confirm libraries are parsed\n    if (typeof gsap === \"undefined\" || typeof ScrollTrigger === \"undefined\") {\n        console.error(\"GSAP or ScrollTrigger engine failed to fetch via CDN.\");\n        return;\n    }\n\n    gsap.registerPlugin(ScrollTrigger);\n    \n    let wrapper = document.querySelector(\'.horizontal-site-wrapper\');\n    let contentTrack = document.querySelector(\'.gsap-horizontal-track\');\n    let bgTrack = document.querySelector(\'.parallax-bg-track\');\n    let sections = gsap.utils.toArray(\'.horizontal-section\');\n    let numSections = sections.length;\n\n    if (contentTrack && numSections > 0) {\n        // Calculate exact cumulative width across layout assets\n        let totalScrollWidth = window.innerWidth * (numSections - 1);\n\n        let tl = gsap.timeline({\n            scrollTrigger: {\n                trigger: wrapper,\n                pin: true,\n                scrub: 0.5, // Ties animation speed tightly to scroll wheel velocity\n                start: \"top top\",\n                end: () => \"+=\" + (window.innerWidth * numSections),\n                invalidateOnRefresh: true,\n                anticipatePin: 1\n            }\n        });\n\n        // 1. Slide content panels sequentially across desktop viewport\n        tl.to(contentTrack, {\n            x: () => -totalScrollWidth,\n            ease: \"none\"\n        }, 0);\n\n        // 2. Slide background track at a 30% speed differential (Parallax depth anchor)\n        if (bgTrack) {\n            tl.to(bgTrack, {\n                x: () => -(totalScrollWidth * 0.3),\n                ease: \"none\"\n            }, 0);\n        }\n        \n        // Force calculations to refresh and lock tracking grids\n        ScrollTrigger.refresh();\n    }\n});\n</script>\n[/ux_html]\n\n<!-- /wp:flatsome/uxbuilder -->','Home','','inherit','closed','closed','','91-revision-v1','','','2026-06-16 07:52:30','2026-06-16 07:52:30','',91,'http://lycos-core.local/?p=101',0,'revision','',0);
