ng cards */\n.content-card {\n    background: rgba(17, 34, 55, 0.85) !important;\n    padding: 3rem !important;\n    border-radius: 12px !important;\n    border: 1px solid rgba(255, 255, 255, 0.1) !important;\n    max-width: 600px !important;\n    color: #ffffff !important;\n}\n</style>\n\n<div class=\"horizontal-site-wrapper\">\n    <div class=\"parallax-bg-track\" style=\"background-image: url(\'/media/Parallax.png\');\"></div>\n    <div class=\"gsap-horizontal-track\">\n        \n        <div class=\"horizontal-section\">\n            <div class=\"content-card\" style=\"text-align: center;\">\n                <h1 style=\"font-size: 3.5rem; color: #ffffff; margin-bottom: 1rem;\">LYCOS CORE</h1>\n                <p style=\"font-size: 1.2rem; opacity: 0.8;\">Scroll down with your mouse wheel to navigate horizontally.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">Architecting Intelligence</h2>\n                <p style=\"opacity: 0.9;\">Custom AI models built to scale operational clarity across local data frameworks.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">System Solutions</h2>\n                <p style=\"opacity: 0.9;\">Designing seamless digital flows for custom web applications and corporate business engines.</p>\n            </div>\n        </div>\n\n    </div>\n</div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n<script>\n(function() {\n    // Intercept engine directly without waiting for complex window wrapper loops\n    function startEngine() {\n        if (typeof gsap === \"undefined\" || typeof ScrollTrigger === \"undefined\") {\n            // If the CDN is lagging, poll again in 50ms\n            setTimeout(startEngine, 50);\n            return;\n        }\n\n        gsap.registerPlugin(ScrollTrigger);\n        \n        let wrapper = document.querySelector(\'.horizontal-site-wrapper\');\n        let contentTrack = document.querySelector(\'.gsap-horizontal-track\');\n        let bgTrack = document.querySelector(\'.parallax-bg-track\');\n        let sections = gsap.utils.toArray(\'.horizontal-section\');\n        let numSections = sections.length;\n\n        if (contentTrack && numSections > 0) {\n            let totalScrollWidth = window.innerWidth * (numSections - 1);\n\n            let tl = gsap.timeline({\n                scrollTrigger: {\n                    trigger: wrapper,\n                    pin: true,\n                    scrub: 0.5,\n                    start: \"top top\",\n                    end: () => \"+=\" + (window.innerWidth * numSections),\n                    invalidateOnRefresh: true,\n                    anticipatePin: 1\n                }\n            });\n\n            // Slide text cards horizontally across desktop screen\n            tl.to(contentTrack, {\n                x: () => -totalScrollWidth,\n                ease: \"none\"\n            }, 0);\n\n            // Move background asset at a 30% velocity track\n            if (bgTrack) {\n                tl.to(bgTrack, {\n                    x: () => -(totalScrollWidth * 0.3),\n                    ease: \"none\"\n                }, 0);\n            }\n            \n            ScrollTrigger.refresh();\n        }\n    }\n\n    // Initialize immediately\n    startEngine();\n})();\n</script>\n[/ux_html]\n\n<!-- /wp:flatsome/uxbuilder -->','Home','','inherit','closed','closed','','91-revision-v1','','','2026-06-16 07:55:57','2026-06-16 07:55:57','',91,'http://lycos-core.local/?p=103',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (104,1,'2026-06-16 07:57:44','2026-06-16 07:57:44','<!-- wp:flatsome/uxbuilder -->\n[ux_html]\n\n<style>\n/* Allow the root document to have a natural scroll height so GSAP can track it */\nhtml, body {\n    margin: 0 !important;\n    padding: 0 !important;\n    background-color: #112237 !important;\n    overflow-x: hidden !important;\n    overflow-y: auto !important;\n    height: auto !important; /* Crucial: Let the document scale organically */\n}\n\n/* Force Flatsome\'s global wrapper container to match the natural flow */\n#wrapper, #main, #content, .page-wrapper {\n    overflow: visible !important;\n    height: auto !important;\n    min-height: 100vh !important;\n    max-width: 100vw !important;\n    padding: 0 !important;\n    margin: 0 !important;\n}\n\n/* Hide theme chrome and titles */\n.page-title, #footer, footer, header, .header-wrapper { \n    display: none !important; \n}\n\n/* The Master Viewport Stage Frame */\n.horizontal-site-wrapper {\n    position: relative !important;\n    width: 100vw !important;\n    height: 100vh !important;\n    overflow: hidden !important;\n}\n\n/* The Continuous Backdrop Graphic Track */\n.parallax-bg-track {\n    position: absolute !important;\n    top: 0 !important;\n    left: 0 !important;\n    height: 100vh !important;\n    width: 250vw !important; /* Wide grid real estate for smooth panning space */\n    background-color: #112237 !important; \n    background-size: cover !important;\n    background-position: left center !important;\n    background-repeat: no-repeat !important;\n    z-index: 1 !important;\n    will-change: transform;\n}\n\n/* The Content Track Layout Row */\n.gsap-horizontal-track {\n    position: relative !important;\n    display: flex !important;\n    flex-wrap: nowrap !important;\n    width: max-content !important;\n    height: 100vh !important;\n    z-index: 2 !important;\n}\n\n/* Single Viewport Presentation Card Slide Panel */\n.horizontal-section {\n    width: 100vw !important;\n    height: 100vh !important;\n    flex-shrink: 0 !important;\n    display: flex !important;\n    align-items: center !important;\n    justify-content: center !important;\n    box-sizing: border-box !important;\n    padding: 10% !important;\n    background: transparent !important;\n}\n\n/* Translucent frosted container boxes */\n.content-card {\n    background: rgba(17, 34, 55, 0.85) !important;\n    padding: 3rem !important;\n    border-radius: 12px !important;\n    border: 1px solid rgba(255, 255, 255, 0.1) !important;\n    max-width: 600px !important;\n    color: #ffffff !important;\n}\n</style>\n\n<div class=\"horizontal-site-wrapper\">\n    <div class=\"parallax-bg-track\" style=\"background-image: url(\'/media/Parallax.png\');\"></div>\n    \n    <div class=\"gsap-horizontal-track\">\n        \n        <div class=\"horizontal-section\">\n            <div class=\"content-card\" style=\"text-align: center;\">\n                <h1 style=\"font-size: 3.5rem; color: #ffffff; margin-bottom: 1rem;\">LYCOS CORE</h1>\n                <p style=\"font-size: 1.2rem; opacity: 0.8;\">Scroll down with your mouse wheel to navigate horizontally.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">Architecting Intelligence</h2>\n                <p style=\"opacity: 0.9;\">Custom AI models built to scale operational clarity across local data frameworks.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">System Solutions</h2>\n                <p style=\"opacity: 0.9;\">Designing seamless digital flows for custom web applications and corporate business engines.</p>\n            </div>\n        </div>\n\n    </div>\n</div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n<script>\n(function() {\n    function runScrollEngine() {\n        // Fallback polling system if CDNs lag behind parsing loops\n        if (typeof gsap === \"undefined\" || typeof ScrollTrigger === \"undefined\") {\n            setTimeout(runScrollEngine, 50);\n            return;\n        }\n\n        gsap.registerPlugin(ScrollTrigger);\n        \n        let wrapper = document.querySelector(\'.horizontal-site-wrapper\');\n        let contentTrack = document.querySelector(\'.gsap-horizontal-track\');\n        let bgTrack = document.querySelector(\'.parallax-bg-track\');\n        let sections = gsap.utils.toArray(\'.horizontal-section\');\n        let numSections = sections.length;\n\n        if (contentTrack && numSections > 0) {\n            // Define total virtual scrolling runway\n            let totalScrollWidth = window.innerWidth * (numSections - 1);\n\n            let tl = gsap.timeline({\n                scrollTrigger: {\n                    trigger: wrapper,\n                    pin: true,           // Freeze window vertical momentum\n                    scrub: 0.5,          // Bind translations to wheel movement\n                    start: \"top top\",\n                    end: () => \"+=\" + totalScrollWidth, // Set runway proportional to track scale\n                    invalidateOnRefresh: true,\n                    anticipatePin: 1\n                }\n            });\n\n            // 1. Shift panel rows to left grid spaces\n            tl.to(contentTrack, {\n                x: () => -totalScrollWidth,\n                ease: \"none\"\n            }, 0);\n\n            // 2. Pan background texture at 30% speed differential\n            if (bgTrack) {\n                tl.to(bgTrack, {\n                    x: () => -(totalScrollWidth * 0.3),\n                    ease: \"none\"\n                }, 0);\n            }\n            \n            // Force recalculations of window coordinate bounds\n            ScrollTrigger.refresh();\n        }\n    }\n\n    // Initialize tracking logic execution loop\n    runScrollEngine();\n})();\n</script>\n[/ux_html]\n\n<!-- /wp:flatsome/uxbuilder -->','Home','','inherit','closed','closed','','91-revision-v1','','','2026-06-16 07:57:44','2026-06-16 07:57:44','',91,'http://lycos-core.local/?p=104',0,'revision','',0);
