on {\n    width: 100vw !important;\n    height: 100vh !important;\n    flex-shrink: 0 !important;\n    display: flex !important;\n    align-items: center !important;\n    justify-content: center !important;\n    box-sizing: border-box !important;\n    padding: 10% !important;\n    background: transparent !important;\n}\n\n/* Translucent floating presentation cards */\n.content-card {\n    background: rgba(17, 34, 55, 0.85) !important;\n    padding: 3rem !important;\n    border-radius: 12px !important;\n    border: 1px solid rgba(255, 255, 255, 0.1) !important;\n    max-width: 600px !important;\n    color: #ffffff !important;\n}\n</style>\n\n<div class=\"horizontal-site-wrapper\">\n    <div class=\"parallax-bg-track\" style=\"background-image: url(\'/media/Parallax.png\');\"></div>\n    <div class=\"gsap-horizontal-track\">\n        \n        <div class=\"horizontal-section\">\n            <div class=\"content-card\" style=\"text-align: center;\">\n                <h1 style=\"font-size: 3.5rem; color: #ffffff; margin-bottom: 1rem;\">LYCOS CORE</h1>\n                <p style=\"font-size: 1.2rem; opacity: 0.8;\">Scroll down with your mouse wheel to navigate horizontally.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">Architecting Intelligence</h2>\n                <p style=\"opacity: 0.9;\">Custom AI models built to scale operational clarity across local data frameworks.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">System Solutions</h2>\n                <p style=\"opacity: 0.9;\">Designing seamless digital flows for custom web applications and corporate business engines.</p>\n            </div>\n        </div>\n\n    </div>\n</div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n<script>\n(function() {\n    function runScrollEngine() {\n        if (typeof gsap === \"undefined\" || typeof ScrollTrigger === \"undefined\") {\n            setTimeout(runScrollEngine, 50);\n            return;\n        }\n\n        gsap.registerPlugin(ScrollTrigger);\n        \n        let wrapper = document.querySelector(\'.horizontal-site-wrapper\');\n        let contentTrack = document.querySelector(\'.gsap-horizontal-track\');\n        let bgTrack = document.querySelector(\'.parallax-bg-track\');\n        let sections = gsap.utils.toArray(\'.horizontal-section\');\n        let numSections = sections.length;\n\n        if (contentTrack && numSections > 0) {\n            let totalScrollWidth = window.innerWidth * (numSections - 1);\n\n            let tl = gsap.timeline({\n                scrollTrigger: {\n                    trigger: wrapper,\n                    pin: true,           // Safely lock the element down inside static contexts\n                    scrub: 0.5,          // Bind translations strictly to wheel speed\n                    start: \"top top\",\n                    end: () => \"+=\" + totalScrollWidth,\n                    invalidateOnRefresh: true,\n                    pinType: \"fixed\"     // Explicitly force standard fixed coordinates\n                }\n            });\n\n            // 1. Horizontally slide text content panels\n            tl.to(contentTrack, {\n                x: () => -totalScrollWidth,\n                ease: \"none\"\n            }, 0);\n\n            // 2. Pan background texture tracking at 30% speed\n            if (bgTrack) {\n                tl.to(bgTrack, {\n                    x: () => -(totalScrollWidth * 0.3),\n                    ease: \"none\"\n                }, 0);\n            }\n            \n            ScrollTrigger.refresh();\n        }\n    }\n\n    runScrollEngine();\n})();\n</script>\n[/ux_html]\n\n<!-- /wp:flatsome/uxbuilder -->','Home','','inherit','closed','closed','','91-revision-v1','','','2026-06-16 07:59:48','2026-06-16 07:59:48','',91,'http://lycos-core.local/?p=105',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (106,1,'2026-06-16 08:02:07','2026-06-16 08:02:07','<!-- wp:flatsome/uxbuilder -->\n[ux_html]\n\n<style>\n/* Reset the master view rules */\nhtml, body {\n    margin: 0 !important;\n    padding: 0 !important;\n    background-color: #112237 !important;\n    width: 100vw !important;\n    height: 100vh !important;\n    overflow: hidden !important; /* Block native window scroll completely */\n}\n\n/* Force structural flattening on everything Flatsome tries to touch */\n#wrapper, #main, #content, .page-wrapper, .main-inner, .ux-builder-placeholder {\n    position: static !important;\n    transform: none !important;\n    perspective: none !important;\n    overflow: visible !important;\n    height: auto !important;\n    width: auto !important;\n    margin: 0 !important;\n    padding: 0 !important;\n}\n\n/* Hide theme artifacts */\n.page-title, #footer, footer, header, .header-wrapper, .back-to-top { \n    display: none !important; \n}\n\n/* * NEW APPROACH: Create a completely sandboxed scroll layer \n * that bypasses the broken browser/theme window viewport tracking.\n */\n.scroll-container {\n    width: 100vw;\n    height: 100vh;\n    overflow-y: scroll;\n    overflow-x: hidden;\n    position: fixed;\n    top: 0;\n    left: 0;\n    z-index: 999999; /* Float over EVERYTHING theme-related */\n}\n\n/* Fixed viewport frame anchor inside the scroll tunnel */\n.horizontal-site-wrapper {\n    position: fixed !important;\n    top: 0 !important;\n    left: 0 !important;\n    width: 100vw !important;\n    height: 100vh !important;\n    overflow: hidden !important;\n    pointer-events: none; /* Let the scroll container capture inputs underneath */\n}\n\n/* Parallax Background Strip */\n.parallax-bg-track {\n    position: absolute !important;\n    top: 0 !important;\n    left: 0 !important;\n    height: 100vh !important;\n    width: 250vw !important;\n    background-color: #112237 !important; \n    background-size: cover !important;\n    background-position: left center !important;\n    background-repeat: no-repeat !important;\n    z-index: 1 !important;\n    will-change: transform;\n}\n\n/* Foreground Horizontal Track */\n.gsap-horizontal-track {\n    position: relative !important;\n    display: flex !important;\n    flex-wrap: nowrap !important;\n    width: max-content !important;\n    height: 100vh !important;\n    z-index: 2 !important;\n}\n\n/* Fullscreen panels */\n.horizontal-section {\n    width: 100vw !important;\n    height: 100vh !important;\n    flex-shrink: 0 !important;\n    display: flex !important;\n    align-items: center !important;\n    justify-content: center !important;\n    box-sizing: border-box !important;\n    padding: 10% !important;\n}\n\n/* Text floating cards */\n.content-card {\n    background: rgba(17, 34, 55, 0.85) !important;\n    padding: 3rem !important;\n    border-radius: 12px !important;\n    border: 1px solid rgba(255, 255, 255, 0.1) !important;\n    max-width: 600px !important;\n    color: #ffffff !important;\n    pointer-events: auto; /* Re-enable clicking inside the cards */\n}\n</style>\n\n<div class=\"scroll-container\">\n    <div class=\"virtual-scroll-height\" style=\"height: 300vh; width: 1px;\"></div>\n</div>\n\n<div class=\"horizontal-site-wrapper\">\n    <div class=\"parallax-bg-track\" style=\"background-image: url(\'/media/Parallax.png\');\"></div>\n    <div class=\"gsap-horizontal-track\">\n        \n        <div class=\"horizontal-section\">\n            <div class=\"content-card\" style=\"text-align: center;\">\n                <h1 style=\"font-size: 3.5rem; color: #ffffff; margin-bottom: 1rem;\">LYCOS CORE</h1>\n                <p style=\"font-size: 1.2rem; opacity: 0.8;\">Scroll down with your mouse wheel to navigate horizontally.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">Architecting Intelligence</h2>\n                <p style=\"opacity: 0.9;\">Custom AI models built to scale operational clarity across local data frameworks.</p>\n            </div>\n        </div>\n\n        <div class=\"horizontal-section\">\n            <div class=\"content-card\">\n                <h2 style=\"font-size: 2.5rem; color: #ffffff; margin-bottom: 1rem;\">System Solutions</h2>\n                <p style=\"opacity: 0.9;\">Designing seamless digital flows for custom web applications and corporate business engines.</p>\n            </div>\n        </div>\n\n    </div>\n</div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n<script>\n(function() {\n    function runScrollEngine() {\n        if (typeof gsap === \"undefined\" || typeof ScrollTrigger === \"undefined\") {\n            setTimeout(runScrollEngine, 50);\n            return;\n        }\n\n        // Violent theme cleanup: strip parent styles using an inline style element injection\n        var styleReset = document.createElement(\'style\');\n        styleReset.innerHTML = \"html,body{overflow:hidden!important;} #wrapper,#main,#content,.page-wrapper{position:static!important;transform:none!important;overflow:visible!important;}\";\n        document.head.appendChild(styleReset);\n\n        gsap.registerPlugin(ScrollTrigger);\n        \n        let scrollContainer = document.querySelector(\'.scroll-container\');\n        let contentTrack = document.querySelector(\'.gsap-horizontal-track\');\n        let bgTrack = document.querySelector(\'.parallax-bg-track\');\n        let sections = gsap.utils.toArray(\'.horizontal-section\');\n        let numSections = sections.length;\n\n        if (contentTrack && numSections > 0 && scrollContainer) {\n            let totalScrollWidth = window.innerWidth * (numSections - 1);\n\n            // Tell ScrollTrigger to watch our isolated proxy tunnel instead of the theme window\n            ScrollTrigger.scrollerProxy(scrollContainer, {\n                scrollTop(value) {\n                    return arguments.length ? scrollContainer.scrollTop = value : scrollContainer.scrollTop;\n                },\n                getBoundingClientRect() {\n                    return {top: 0, left: 0, width: window.innerWidth, height: window.innerHeight};\n                }\n            });\n\n            let tl = gsap.timeline({\n                scrollTrigger: {\n                    trigger: \".virtual-scroll-height\",\n                    scroller: scrollContainer, // Watch the sandbox tunnel\n                    scrub: 0.5,\n                    start: \"top top\",\n                    end: \"bottom bottom\",\n                    invalidateOnRefresh: true\n                }\n            });\n\n            // Slide text cards horizontally\n            tl.to(contentTrack, {\n                x: () => -totalScrollWidth,\n                ease: \"none\"\n            }, 0);\n\n            // Pan background track at 30% speed\n            if (bgTrack) {\n                tl.to(bgTrack, {\n                    x: () => -(totalScrollWidth * 0.3),\n                    ease: \"none\"\n                }, 0);\n            }\n            \n            ScrollTrigger.refresh();\n        }\n    }\n\n    runScrollEngine();\n})();\n</script>\n[/ux_html]\n\n<!-- /wp:flatsome/uxbuilder -->','Home','','inherit','closed','closed','','91-revision-v1','','','2026-06-16 08:02:07','2026-06-16 08:02:07','',91,'http://lycos-core.local/?p=106',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (107,1,'2026-06-16 08:08:34','2026-06-16 08:08:34','<!-- wp:flatsome/uxbuilder -->\n[ux_html]\n\n<style>\n/* Document level constraints */\nhtml, body {\n    margin: 0 !important;\n    padding: 0 !important;\n    background-color: #112237 !important;\n    width: 100vw !important;\n    height: 100vh !important;\n    overflow: hidden !important;\n}\n\n/* Force theme containers to behave as a neutral structural canvas */\n#wrapper, #main, #content, .page-wrapper, .main-inner, .ux-builder-placeholder {\n    position: static !important;\n    transform: none !important;\n    perspective: none !important;\n    overflow: visible !important;\n    height: auto !important;\n    width: auto !important;\n    margin: 0 !important;\n    padding: 0 !important;\n}\n\n/* Hide header, footer, page titles, and back-to-top buttons */\n.page-title, #footer, footer, header, .header-wrapper, .back-to-top { \n    display: none !important; \n}\n\n/* Isolated Sandboxed Scroll Layer */\n.scroll-container {\n    width: 100vw;\n    height: 100vh;\n    overflow-y: scroll;\n    overflow-x: hidden;\n    position: fixed;\n    top: 0;\n    left: 0;\n    z-index: 999999;\n}\n/* Hide the proxy scrollbar visually while keeping wheel inputs live */\n.scroll-container::-webkit-scrollbar { display: none !important; width: 0 !important; }\n.scroll-container { -ms-overflow-style: none !important; scrollbar-width: none !important; }\n\n/* Fixed view viewport frame anchor over the theme canvas */\n.horizontal-site-wrapper {\n    position: fixed !important;\n    top: 0 !important;\n    left: 0 !important;\n    width: 100vw !important;\n    height: 100vh !important;\n    overflow: hidden !important;\n    pointer-events: none;\n}\n\n/* Background Sheet Track Layer */\n.parallax-bg-track {\n    position: absolute !important;\n    top: 0 !important;\n    left: 0 !important;\n    height: 100vh !important;\n    width: 250vw !important; /* Panning real estate */\n    background-color: #11