ion, .page-wrapper > .section\');\n        if(nativeSections.length === 0) {\n            nativeSections = document.querySelectorAll(\'.main-inner > .section, .main-inner > div > .section\');\n        }\n\n        nativeSections.forEach(section => {\n            trackTarget.appendChild(section);\n        });\n\n        let sections = gsap.utils.toArray(\'#visual-builder-content-target > .section\');\n        let numSections = sections.length;\n\n        if (numSections > 0 && scrollContainer) {\n            let totalScrollWidth = window.innerWidth * (numSections - 1);\n            let viewportHeight = window.innerHeight;\n            \n            // Allocate 100vh of vertical runway for each section\n            document.querySelector(\'.virtual-scroll-height\').style.height = (numSections * 100) + \"vh\";\n\n            ScrollTrigger.scrollerProxy(scrollContainer, {\n                scrollTop(value) {\n                    return arguments.length ? scrollContainer.scrollTop = value : scrollContainer.scrollTop;\n                },\n                getBoundingClientRect() {\n                    return {top: 0, left: 0, width: window.innerWidth, height: window.innerHeight};\n                }\n            });\n\n            let tl = gsap.timeline({\n                scrollTrigger: {\n                    trigger: \".virtual-scroll-height\",\n                    scroller: scrollContainer,\n                    scrub: 0.5,\n                    start: \"top top\",\n                    end: \"bottom bottom\",\n                    invalidateOnRefresh: true\n                }\n            });\n\n            tl.to(trackTarget, {\n                x: () => -totalScrollWidth,\n                ease: \"none\"\n            }, 0);\n\n            if (bgTrack) {\n                tl.to(bgTrack, {\n                    x: () => -(totalScrollWidth * 0.3),\n                    ease: \"none\"\n                }, 0);\n            }\n            \n            ScrollTrigger.refresh();\n\n            // * NATIVE SCROLL TIMEOUT OVERRIDE *\n            // Listens directly to the proxy scroller container to intercept inertial coasting\n            let isSnapping = false;\n            let scrollTimeout;\n\n            scrollContainer.addEventListener(\'scroll\', () => {\n                if (isSnapping) return;\n\n                clearTimeout(scrollTimeout);\n                scrollTimeout = setTimeout(() => {\n                    let currentScroll = scrollContainer.scrollTop;\n                    \n                    // Determine which section index the user is closest to\n                    let closestSectionIndex = Math.round(currentScroll / viewportHeight);\n                    let targetScrollPosition = closestSectionIndex * viewportHeight;\n\n                    // Force safe boundary limits\n                    if (targetScrollPosition < 0) targetScrollPosition = 0;\n                    if (targetScrollPosition > (numSections - 1) * viewportHeight) {\n                        targetScrollPosition = (numSections - 1) * viewportHeight;\n                    }\n\n                    // If we aren\'t perfectly aligned, engage a smooth layout correction animate snap\n                    if (currentScroll !== targetScrollPosition) {\n                        isSnapping = true;\n                        gsap.to(scrollContainer, {\n                            scrollTop: targetScrollPosition,\n                            duration: 0.4,\n                            ease: \"power2.out\",\n                            onComplete: () => {\n                                isSnapping = false;\n                            }\n                        });\n                    }\n                }, 60); // 60ms delay after scroll momentum settles down\n            });\n        }\n    }\n\n    window.addEventListener(\'load\', function() {\n        setTimeout(initVisualEngine, 150);\n    });\n})();\n</script>\n[/ux_html]\n[section height=\"100vh\"]\n\n[ux_text text_align=\"center