INSERT INTO `wp_posts` VALUES (270,1,'2026-06-18 15:00:16','2026-06-18 15:00:16','<!-- wp:flatsome/uxbuilder -->\n[ux_html label=\"Menu\"]\n\n<header class=\"lycos-global-fixed-header\">\n    <img src=\"/media/LYCOS-CORE-lOGOTYPE.png\" alt=\"Lycos Core\" class=\"lycos-nav-identity\">\n    \n    <nav class=\"lycos-nav-links-box\">\n        <a href=\"#\" class=\"lycos-nav-item\">\n            Our Pillars \n            <svg width=\"10\" height=\"6\" viewBox=\"0 0 500 500\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M1 1L5 5L9 1\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>\n        </a>\n        <a href=\"#\" class=\"lycos-nav-item\">Incubation Hub</a>\n        <a href=\"#\" class=\"lycos-nav-item\">About Us</a>\n        <a href=\"#\" class=\"lycos-nav-item\">Insights</a>\n    </nav>\n    \n    <a href=\"#\" class=\"lycos-nav-action btn-contact-nav\">Contact Us</a>\n</header>\n[/ux_html]\n[ux_html label=\"Horisontal Scroll implementation\"]\n\n<style>\n/* Reset and Container Setup */\nhtml, body { margin: 0; padding: 0; overflow-x: hidden; width: 100%; }\n\n/* The container matches the viewport */\n#main-scroll-trigger {\n    width: 100vw;\n    height: 100vh;\n    overflow: hidden;\n    position: relative;\n    background-image: url(\'/media/Parallax.png\');\n    background-size: cover;\n    background-position: center;\n}\n\n.gsap-horizontal-track {\n    display: flex;\n    flex-wrap: nowrap;\n    width: max-content;\n    height: 100vh;\n}\n\n.gsap-horizontal-track > .section {\n    width: 100vw;\n    height: 100vh;\n    flex-shrink: 0;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background-color: transparent !important;\n}\n</style>\n\n<div id=\"main-scroll-trigger\">\n    <div class=\"gsap-horizontal-track\" id=\"visual-builder-content-target\"></div>\n</div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n<script>\nwindow.addEventListener(\'load\', function() {\n    let trackTarget = document.getElementById(\'visual-builder-content-target\');\n    let nativeSections = document.querySelectorAll(\'.section\');\n    nativeSections.forEach(section => { trackTarget.appendChild(section); });\n\n    let sections = gsap.utils.toArray(\'.section\');\n    let totalWidth = (sections.length - 1) * window.innerWidth;\n\n    // Use a timeline that is linked to scroll without \"pinning\" the whole page\n    gsap.to(trackTarget, {\n        x: -totalWidth,\n        ease: \"none\",\n        scrollTrigger: {\n            trigger: \"#main-scroll-trigger\",\n            scrub: 1,\n            start: \"top top\",\n            end: \"+=3000\", // Adjust this value to control scroll speed/duration\n            pin: false,    // Turned OFF to fix your nav and jump issues\n            invalidateOnRefresh: true\n        }\n    });\n});\n</script>\n[/ux_html]\n[section label=\"Page 1 - Desktop\" height=\"100vh\"]\n\n[row width=\"custom\" custom_width=\"80%\" v_align=\"equal\" padding=\"100px 0px 0px 0px\"]\n\n[col span=\"6\" span__sm=\"12\"]\n\n<p style=\"font-size: 13px; text-transform: uppercase; letter-spacing: 3px; color: rgba(255, 255, 255, 0.6); margin-bottom: 15px; font-weight: 600;\">\n    AI That Powers Better Financial Decisions\n</p>\n<h1 style=\"font-size: 58px; font-weight: 800; color: #ffffff; line-height: 1.2; margin-bottom: 35px; letter-spacing: -1px;\">\n    Strategic Intelligence.<br />\n    <span style=\"color: rgba(255, 255, 255, 0.35); display: block; margin: 5px 0;\">Accelerated Core Building.</span><br />\n    Built for the Future.<br />\n</h1>\n[row_inner]\n\n[col_inner span=\"6\" span__sm=\"12\"]\n\n[button text=\"Explore Services\" size=\"xlarge\" radius=\"10\" class=\"lycos-hero-btn-solid\"]\n\n\n[/col_inner]\n[col_inner span=\"6\" span__sm=\"12\"]\n\n[button text=\"Partner with us\" color=\"success\" style=\"outline\" size=\"xlarge\" radius=\"10\" class=\"lycos-hero-btn-outline\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n[col span=\"6\" span__sm=\"12\"]\n\n[ux_html]\n\n<div style=\"width: 100%; height: 500px; position: relative;\">\n    <svg id=\"network-svg\" viewBox=\"0 0 500 500\" preserveAspectRatio=\"xMidYMid slice\" style=\"width: 100%; height: 100%; overflow: visible;\">\n        <g id=\"lines\" stroke=\"#a3ff33\" stroke-width=\"0.8\" opacity=\"0.5\"></g>\n        <g id=\"nodes\" fill=\"#00d4ff\"></g>\n        <g id=\"ai-node\" style=\"filter: drop-shadow(0 0 8px rgba(163, 255, 51, 0.5));\">\n            <circle cx=\"250\" cy=\"250\" r=\"45\" fill=\"rgba(17, 34, 55, 0.9)\" stroke=\"#a3ff33\" stroke-width=\"2\" />\n            <text x=\"250\" y=\"258\" font-family=\"sans-serif\" font-weight=\"bold\" font-size=\"24\" fill=\"#a3ff33\" text-anchor=\"middle\">AI</text>\n        </g>\n    </svg>\n</div>\n[/ux_html]\n\n[/col]\n\n[/row]\n[row]\n\n[col span__sm=\"12\"]\n\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff;\">Our technology partners</span></h2>\n\n[/col]\n\n[/row]\n[row]\n\n[col span__sm=\"12\"]\n\n\n[/col]\n\n[/row]\n[ux_html]\n\n<div style=\"display: grid; grid-template-columns: repeat(3, 1fr); align-items: center; justify-items: center; gap: 20px; padding: 20px;\">\n  \n  <div style=\"height: 50px; display: flex; align-items: center;\">\n    <img src=\"https://cdn.jsdelivr.net/gh/gilbarbara/logos@master/logos/google-cloud.svg\" \n         style=\"height: 100%; width: auto; filter: brightness(0) invert(1);\" alt=\"Google Cloud\">\n  </div>\n       \n  <div style=\"height: 50px; display: flex; align-items: center;\">\n    <img src=\"https://cdn.jsdelivr.net/gh/gilbarbara/logos@master/logos/aws.svg\" \n         style=\"height: 100%; width: auto; filter: brightness(0) invert(1);\" alt=\"AWS\">\n  </div>\n       \n  <div style=\"height: 50px; display: flex; align-items: center;\">\n    <img src=\"https: