INSERT INTO `wp_posts` VALUES (302,1,'2026-06-18 16:00:10','2026-06-18 16:00:10','<!-- wp:flatsome/uxbuilder -->\n[ux_html label=\"Menu\"]\n\n<header class=\"lycos-global-fixed-header\">\n    <div class=\"lycos-nav-identity\">\n        <img src=\"/media/LYCOS-CORE-lOGOTYPE.png\" alt=\"Lycos Core\">\n    </div>\n    <nav class=\"lycos-nav-links-box\">\n        <a href=\"#\">Our Pillars</a>\n        <a href=\"#\">Incubation Hub</a>\n        <a href=\"#\">About Us</a>\n        <a href=\"#\">Insights</a>\n    </nav>\n    <a href=\"#\" class=\"lycos-hero-btn-solid\">Contact Us</a>\n</header>\n[/ux_html]\n[ux_html label=\"Horisontal Scroll implementation\"]\n\n<div id=\"main-scroll-trigger\">\n    <div class=\"gsap-horizontal-track\" id=\"track\">\n        <div class=\"section\">Section 1 Content</div>\n        <div class=\"section\">Section 2 Content</div>\n        <div class=\"section\">Section 3 Content</div>\n    </div>\n</div>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n<script>\nwindow.addEventListener(\'load\', () => {\n    gsap.registerPlugin(ScrollTrigger);\n\n    let sections = gsap.utils.toArray(\".section\");\n\n    gsap.to(\"#track\", {\n        x: () => -1 * (document.getElementById(\'track\').scrollWidth - window.innerWidth),\n        ease: \"none\",\n        scrollTrigger: {\n            trigger: \"#main-scroll-trigger\",\n            pin: true,\n            scrub: 1,\n            end: () => \"+=\" + (document.getElementById(\'track\').scrollWidth - window.innerWidth),\n            snap: 1 / (sections.length - 1)\n        }\n    });\n});\n</script>\n[/ux_html]\n[section label=\"Page 1 - Desktop\" height=\"100vh\" class=\"section\"]\n\n[row width=\"custom\" custom_width=\"80%\" v_align=\"equal\" padding=\"100px 0px 0px 0px\"]\n\n[col span=\"6\" span__sm=\"12\"]\n\n<p style=\"font-size: 13px; text-transform: up