INSERT INTO `wp_posts` VALUES (312,1,'2026-06-18 16:24:46','2026-06-18 16:24:46','<!-- wp:flatsome/uxbuilder -->\n[ux_html label=\"Menu\"]\n\n<header class=\"lycos-global-fixed-header\">\n    <div class=\"lycos-nav-identity\">\n        <img src=\"/media/LYCOS-CORE-lOGOTYPE.png\" alt=\"Lycos Core\">\n    </div>\n    <nav class=\"lycos-nav-links-box\">\n        <a href=\"#\">Our Pillars</a>\n        <a href=\"#\">Incubation Hub</a>\n        <a href=\"#\">About Us</a>\n        <a href=\"#\">Insights</a>\n    </nav>\n    <a href=\"#\" class=\"lycos-hero-btn-solid\">Contact Us</a>\n</header>\n[/ux_html]\n[ux_html label=\"Horisontal Scroll implementation\"]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n<script>\nwindow.addEventListener(\'load\', () => {\n    // 1. Create the wrapper that forces horizontal alignment\n    const container = document.createElement(\'div\');\n    container.style.display = \'flex\';\n    container.style.flexDirection = \'row\';\n    container.style.width = \'max-content\';\n    container.id = \'scroll-wrapper\';\n    \n    // 2. Move all builder sections into the wrapper\n    const sections = document.querySelectorAll(\'.section\');\n    document.body.prepend(container);\n    sections.forEach(s => container.appendChild(s));\n\n    // 3. GSAP Horizontal Scroll\n    gsap.registerPlugin(ScrollTrigger);\n    \n    gsap.to(container, {\n        x: () => -(container.scrollWidth - window.innerWidth),\n        ease: \"none\",\n        scrollTrigger: {\n            trigger: container,\n            pin: true,\n            scrub: 1,\n            end: () => \"+=\" + (container.scrollWidth - window.innerWidth),\n            snap: 1 / (sections.length - 1),\n            invalidateOnRefresh: true\n        }\n    });\n});\n</script>\n[/ux_html]\n[section label=\"Page 1 - Desktop\" height=\"100vh\" class=\"section\"