INSERT INTO `wp_posts` VALUES (396,1,'2026-06-19 08:30:53','2026-06-19 08:30:53','<!-- wp:flatsome/uxbuilder -->\n[row style=\"collapse\" width=\"full-width\" h_align=\"center\"]\n\n[col span__sm=\"12\" align=\"center\"]\n\n\n[/col]\n\n[/row]\n[ux_html label=\"Menu\"]\n\n<header class=\"lycos-global-fixed-header\">\n    <a href=\"/\" class=\"lycos-nav-identity\">\n        <img src=\"/media/LYCOS-CORE-lOGOTYPE.png\" alt=\"Lycos Core Logo\">\n    </a>\n\n    <nav class=\"lycos-nav-links-box\">\n        <div class=\"nav-dropdown\">\n            <a href=\"#\">Our Pillars</a>\n            <div class=\"dropdown-content\">\n                <a href=\"/ai-consulting/\">AI Consulting</a>\n                <a href=\"/ai-solutions/\">AI Solutions</a>\n                <a href=\"/tech-services/\">Tech Services</a>\n            </div>\n        </div>\n\n        <a href=\"/incubation-hub/\">Incubation Hub</a>\n\n        <div class=\"nav-dropdown\">\n            <a href=\"#\">About Us</a>\n            <div class=\"dropdown-content\">\n                <a href=\"/who-we-are/\">Who We Are</a>\n                <a href=\"/how-we-operate/\">How We Operate</a>\n                <a href=\"/governance-and-security-standards/\">Governance & Security Standards</a>\n            </div>\n        </div>\n\n        <div class=\"nav-dropdown\">\n            <a href=\"#\">Insights</a>\n            <div class=\"dropdown-content\">\n                <a href=\"/case-studies/\">Case Studies</a>\n                <a href=\"/executive-briefing/\">Executive Briefing</a>\n                <a href=\"/market-trends/\">Market Trends and Research</a>\n            </div>\n        </div>\n\n        <a href=\"/partner-with-us/\">Partner with Us</a>\n        <a href=\"/contact-us/\" class=\"lycos-hero-btn-solid\">Contact Us</a>\n    </nav>\n</header>\n[/ux_html]\n[ux_html label=\"Horisontal Scroll implementation\"]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n<div id=\"parallax-bg\"></div>\n\n<div id=\"scroll-wrapper\" style=\"display: flex; flex-wrap: nowrap; width: fit-content; height: 100vh;\"></div>\n\n<script>\nhistory.scrollRestoration = \'manual\';\n\nwindow.addEventListener(\'load\', () => {\n    const sections = document.querySelectorAll(\'.section\');\n    const wrapper = document.getElementById(\'scroll-wrapper\');\n    const bg = document.getElementById(\'parallax-bg\');\n\n    sections.forEach(s => {\n        s.style.width = \'100vw\';\n        s.style.height = \'100vh\';\n        s.style.flexShrink = \'0\';\n        wrapper.appendChild(s);\n    });\n\n    gsap.registerPlugin(ScrollTrigger);\n\n    // Timeline for coordinated movement\n    let tl = gsap.timeline({\n        scrollTrigger: {\n            trigger: \"body\",\n            pin: true,\n            scrub: 1, \n            start: \"top top\",\n            end: () => \"+=\" + (wrapper.scrollWidth - window.innerWidth),\n            snap: {\n                snapTo: 1 / (sections.length - 1),\n                duration: { min: 0.5, max: 0.8 },\n                ease: \"power2.inOut\",\n                delay: 0\n            },\n            invalidateOnRefresh: true\n        }\n    });\n\n    // Move the content\n    tl.to(wrapper, { x: () => -(wrapper.scrollWidth - window.innerWidth), ease: \"none\" }, 0);\n    \n    // Move the background slower (-10% of the movement) for the parallax effect\n    tl.to(bg, { xPercent: -10, ease: \"none\" }, 0);\n\n    setTimeout(() => {\n        window.scrollTo(0, 0);\n        ScrollTrigger.refresh();\n    }, 500);\n});\n</script>\n[/ux_html]\n[section label=\"Page 1 - Desktop\" height=\"100vh\" class=\"section\"]\n\n[row width=\"custom\" custom_width=\"80%\" v_align=\"equal\" h_align=\"right\" padding=\"100px 0px 0px 0px\"]\n\n[col span=\"2\" span__sm=\"12\"]\n\n\n[/col]\n[col span=\"5\" span__sm=\"12\" align=\"right\"]\n\n<p style=\"fo