INSERT INTO `wp_posts` VALUES (561,1,'2026-06-25 09:44:22','2026-06-25 09:44:22','<!-- wp:flatsome/uxbuilder -->\n[row style=\"collapse\" width=\"full-width\" h_align=\"center\"]\n\n[col span__sm=\"12\" align=\"center\" class=\"floating-header-container\"]\n\n[block id=\"383\"]\n\n\n[/col]\n\n[/row]\n[ux_html label=\"Horisontal Scroll implementation\"]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/gsap.min.js\"></script>\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.2/ScrollTrigger.min.js\"></script>\n\n<div id=\"parallax-bg\"></div>\n\n<div id=\"scroll-wrapper\" style=\"display: flex; flex-wrap: nowrap; width: fit-content; height: 100vh;\"></div>\n\n<script>\nhistory.scrollRestoration = \'manual\';\n\nwindow.addEventListener(\'load\', () => {\n    const sections = document.querySelectorAll(\'.section\');\n    const wrapper = document.getElementById(\'scroll-wrapper\');\n    const bg = document.getElementById(\'parallax-bg\');\n\n    sections.forEach(s => {\n        s.style.width = \'100vw\';\n        s.style.height = \'100vh\';\n        s.style.flexShrink = \'0\';\n        wrapper.appendChild(s);\n    });\n\n    gsap.registerPlugin(ScrollTrigger);\n\n    // Timeline for coordinated movement\n    let tl = gsap.timeline({\n        scrollTrigger: {\n            trigger: \"body\",\n            pin: true,\n            scrub: 1, \n            start: \"top top\",\n            end: () => \"+=\" + (wrapper.scrollWidth - window.innerWidth),\n            snap: {\n                snapTo: 1 / (sections.length - 1),\n                duration: { min: 0.5, max: 0.8 },\n                ease: \"power2.inOut\",\n                delay: 0\n            },\n            invalidateOnRefresh: true\n        }\n    });\n\n    // Move the content\n    tl.to(wrapper, { x: () => -(wrapper.scrollWidth - window.innerWidth), ease: \"none\" }, 0);\n    \n    // Move the background slower (-10% of the movement) for the parallax effect\n    tl.to(bg, { xPercent: -10, ease: \"none\" }, 0);\n\n    setTimeout(() => {\n        window.scrollTo(0, 0);\n        ScrollTrigger.refresh();\n    }, 500);\n});\n</script>\n[/ux_html]\n[section label=\"Page 1 - Desktop\" height=\"100vh\" class=\"section\"]\n\n[divider height=\"20px\"]\n\n[row width=\"custom\" custom_width=\"80%\" v_align=\"equal\" h_align=\"right\" padding=\"0px 0px 0px 0px\"]\n\n[col span=\"6\" span__sm=\"12\" align=\"right\"]\n\n<p style=\"font-size: 11px; text-transform: uppercase; letter-spacing: 3px; color: rgba(255, 255, 255, 0.6); margin-bottom: 15px; font-weight: 600;\">\n    AI That Powers Better Financial Decisions\n</p>\n<h1 style=\"font-size: 50px; font-weight: 800; color: #ffffff; line-height: 1.2; margin-bottom: 35px; letter-spacing: -1px;\">\n    Strategic Intelligence.<br />\n    <span style=\"color: rgba(255, 255, 255, 0.5); display: block; margin: 5px 0;\">Accelerated Core Building.</span><br />\n    Built for the Future.<br />\n</h1>\n[row_inner]\n\n[col_inner span=\"6\" span__sm=\"12\"]\n\n[button text=\"Explore Services\" size=\"xlarge\" radius=\"10\" class=\"lycos-hero-btn-solid\"]\n\n\n[/col_inner]\n[col_inner span=\"6\" span__sm=\"12\"]\n\n[button text=\"Partner with us\" color=\"success\" style=\"outline\" size=\"xlarge\" radius=\"10\" class=\"lycos-hero-btn-outline\"]\n\n\n[/col_inner]\n\n[/row_inner]\n\n[/col]\n[col span=\"6\" span__sm=\"12\"]\n\n[ux_html]\n\n<div style=\"width: 100%; height: 500px; position: relative;\">\n    <svg id=\"network-svg\" viewBox=\"0 0 500 500\" preserveAspectRatio=\"xMidYMid slice\" style=\"width: 100%; height: 100%; overflow: visible;\">\n        <g id=\"lines\" stroke=\"#a3ff33\" stroke-width=\"0.8\" opacity=\"0.5\"></g>\n        <g id=\"nodes\" fill=\"#00d4ff\"></g>\n        <g id=\"ai-node\" style=\"filter: drop-shadow(0 0 8px rgba(163, 255, 51, 0.5));\">\n            <circle cx=\"250\" cy=\"250\" r=\"45\" fill=\"rgba(17, 34, 55, 0.9)\" stroke=\"#a3ff33\" stroke-width=\"2\" />\n            <text x=\"250\" y=\"258\" font-family=\"sans-serif\" font-weight=\"bold\" font-size=\"24\" fill=\"#a3ff33\" text-anchor=\"middle\">AI</text>\n        </g>\n    </svg>\n</div>\n[/ux_html]\n\n[/col]\n\n[/row]\n[row]\n\n[col span__sm=\"12\"]\n\n<h2 style=\"text-align: center;\"><span style=\"color: #ffffff;\">Our technology partners</span></h2>\n\n[/col]\n\n[/row]\n[row]\n\n[col span__sm=\"12\"]\n\n\n[/col]\n\n[/row]\n[ux_html]\n\n<div style=\"display: grid; grid-template-columns: repeat(3, 1fr); align-items: center; justify-items: center; gap: 20px; padding: 20px;\">\n  \n  <div style=\"height: 50px; display: flex; align-items: center;\">\n    <img src=\"https://cdn.jsdelivr.net/gh/gilbarbara/logos@master/logos/google-cloud.svg\" \n         style=\"height: 100%; width: auto; filter: brightness(0) invert(1);\" alt=\"Google Cloud\">\n  </div>\n       \n  <div style=\"height: 50px; display: flex; align-items: center;\">\n    <img src=\"https://cdn.jsdelivr.net/gh/gilbarbara/logos@master/logos/aws.svg\" \n         style=\"height: 100%; width: auto; filter: brightness(0) invert(1);\" alt=\"AWS\">\n  </div>\n       \n  <div style=\"height: 50px; display: flex; align-items: center;\">\n    <img src=\"https://cdn.jsdelivr.net/gh/gilbarbara/logos@master/logos/anthropic-claude.svg\" \n         style=\"height: 100%; width: auto; filter: brightness(0) invert(1);\" alt=\"Claude\">\n  </div>\n</div>\n[/ux_html]\n\n[/section]\n[section label=\"Page 2 - Desktop\" height=\"100vh\" class=\"section\"]\n\n[row h_align=\"center\"]\n\n[col span__sm=\"12\"]\n\n[ux_text text_align=\"center\" text_color=\"rgb(255,255,255)\"]\n\n<p><span style=\"font-size: 250%;\"><span style=\"color: #8ce63f;\">Our Pillars</span> for growth</span></p>\n[/ux_text]\n\n[/col]\n\n[/row]\n[row width=\"custom\" custom_width=\"80%\" v_align=\"equal\" class=\"lycos-pillar-row\"]\n\n[col span=\"3\" span__sm=\"6\" bg_color=\"rgb(17, 34, 55)\" bg_radius=\"8\" class=\"lycos-pillar-card\"]\n\n[featured_box img=\"491\" icon_color=\"rgb(140, 23