INSERT INTO `wp_posts` VALUES (629,1,'2026-06-29 06:50:41','2026-06-29 06:50:41','[ux_html]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.3.2/papaparse.min.js\"></script>\n\n<div id=\"calc-ui\">\n    <h3>Select Location</h3>\n    \n    <select id=\"continentSelect\" onchange=\"updateCountryDropdown()\">\n        <option value=\"\">-- Select Continent --</option>\n    </select>\n    \n    <select id=\"countrySelect\">\n        <option value=\"\">-- Select Country --</option>\n    </select>\n    \n    <button onclick=\"runCalc()\">Calculate ROI</button>\n    <div id=\"resultsTable\"></div>\n</div>\n\n<script>\n// REPLACE THESE WITH YOUR PUBLISHED CSV LINKS\nconst sheet1_url = \'YOUR_PUBLISHED_CSV_LINK_1\'; \nconst sheet2_url = \'YOUR_PUBLISHED_CSV_LINK_2\';\n\nlet rawData = {};\n\n// Fetch data on load\nasync function fetchLiveData() {\n    Papa.parse(sheet1_url, {\n        download: true, header: true, complete: function(results) {\n            // Populate country dropdown here\n        }\n    });\n    // Repeat for sheet 2...\n}\n\nfunction runCalc() {\n    // Math logic goes here, using the \'rawData\' variables\n    // This will always be up to date with the sheet!\n}\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 06:50:41','2026-06-29 06:50:41','',615,'http://lycos-core.local/?p=629',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (630,1,'2026-06-29 06:53:43','2026-06-29 06:53:43','[ux_html]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.3.2/papaparse.min.js\"></script>\n\n<div id=\"calc-ui\" style=\"color: white; padding: 20px; font-family: sans-serif;\">\n    <h3>ROI Calculator</h3>\n    \n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" onchange=\"updateCountryDropdown()\" style=\"width:100%; color:black; padding:5px;\">\n        <option value=\"\">-- Select Continent --</option>\n    </select><br><br>\n\n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:5px;\">\n        <option value=\"\">-- Select Country --</option>\n    </select><br><br>\n\n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; color:black; padding:5px;\"><br><br>\n\n    <button onclick=\"runCalc()\" style=\"cursor:pointer; background:#CAFF00; border:none; padding:10px 20px; font-weight:bold; color:black;\">CALCULATE ROI</button>\n    \n    <div id=\"resultsTable\" style=\"margin-top:20px; overflow-x:auto;\"></div>\n</div>\n\n<script>\nconst sheet1_url = \'https://docs.google.com/spreadsheets/d/e/2PACX-1vQXuD8yBuovR32Qx_MvqpHAxx_Lq8uSPOOSkJ1ihtdsMs9FNIdaJKzaAIYifgocJXVQt30949WZcxzn/pub?output=csv\';\nconst sheet2_url = \'https://docs.google.com/spreadsheets/d/e/2PACX-1vR9j5cnQbY_wkcNGH9M6xW2o4wnSZdrmuEWdEDkZoZr-9dCTctjJ_h1N8SAS05sVRzrenCCnA8jJApz/pub?output=csv\';\n\nlet rawData = { sheet1: [], sheet2: [] };\n\n// Initialize Data\nPapa.parse(sheet1_url, { download: true, header: true, complete: function(results) {\n    rawData.sheet1 = results.data;\n    const continents = [...new Set(rawData.sheet1.map(item => item.continent_id).filter(Boolean))];\n    const select = document.getElementById(\'continentSelect\');\n    continents.forEach(cont => select.innerHTML += `<option value=\"${cont}\">${cont}</option>`);\n}});\n\nPapa.parse(sheet2_url, { download: true, header: true, complete: function(results) {\n    rawData.sheet2 = results.data[0]; \n}});\n\nfunction updateCountryDropdown() {\n    const selectedContinent = document.getElementById(\'continentSelect\').value;\n    const countrySelect = document.getElementById(\'countrySelect\');\n    const filtered = rawData.sheet1.filter(c => c.continent_id === selectedContinent);\n    countrySelect.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n    filtered.forEach(c => countrySelect.innerHTML += `<option value=\"${c.display_name}\">${c.display_name}</option>`);\n}\n\nfunction runCalc() {\n    const country = rawData.sheet1.find(c => c.display_name === document.getElementById(\'countrySelect\').value);\n    const build = rawData.sheet2;\n    const volume = parseFloat(document.getElementById(\'monthlyVolume\').value);\n    \n    if (!country) return alert(\'Please select a country\');\n\n    let html = \'<table border=\"1\" style=\"width:100%; border-collapse:collapse; text-align:center; color:white; border-color:white;\">\';\n    html += \'<tr style=\"background:#1a2b45;\"><th>Year</th><th>Human Cost</th><th>AI Cost</th><th>Savings</th></tr>\';\n    \n    for (let y = 1; y <= 5; y++) {\n        let humanCost = (parseFloat(country.avg_salary) + parseFloat(country.operating_cost)) * 12 * Math.pow(1 + parseFloat(country.avg_increase.replace(\'%\', \'\'))/100, y - 1);\n        let retainer = parseFloat(build[`year_${y}_retainer`]);\n        let aiQueryCost = (parseFloat(build.voice_per_query) + parseFloat(build.llm_per_query)) * volume * 12;\n        let aiTotal = retainer + aiQueryCost + (y === 1 ? parseFloat(build.initial_cost) : 0);\n        \n        html += `<tr><td>${y}</td><td>$${humanCost.toFixed(0)}</td><td>$${aiTotal.toFixed(0)}</td><td>$${(humanCost - aiTotal).toFixed(0)}</td></tr>`;\n    }\n    document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n}\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 06:53:43','2026-06-29 06:53:43','',615,'http://lycos-core.local/?p=630',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (631,1,'2026-06-29 06:55:53','2026-06-29 06:55:53','[ux_html]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.3.2/papaparse.min.js\"></script>\n\n<div id=\"calc-ui\" style=\"color: white; padding: 20px; font-family: sans-serif;\">\n    <h3 style=\"color:#CAFF00;\">ROI Calculator</h3>\n    \n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" onchange=\"updateCountryDropdown()\" style=\"width:100%; color:black; padding:5px; margin-bottom:15px;\">\n        <option value=\"\">-- Select Continent --</option>\n    </select>\n\n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:5px; margin-bottom:15px;\">\n        <option value=\"\">-- Select Country --</option>\n    </select>\n\n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; color:black; padding:5px; margin-bottom:15px;\">\n\n    <button onclick=\"runCalc()\" style=\"cursor:pointer; background:#CAFF00; border:none; padding:10px 20px; font-weight:bold; color:black; width:100%;\">CALCULATE ROI</button>\n    \n    <div id=\"resultsTable\" style=\"margin-top:20px; overflow-x:auto;\"></div>\n</div>\n\n<script>\nconst sheet1_url = \'https://docs.google.com/spreadsheets/d/e/2PACX-1vQXuD8yBuovR32Qx_MvqpHAxx_Lq8uSPOOSkJ1ihtdsMs9FNIdaJKzaAIYifgocJXVQt30949WZcxzn/pub?output=csv\';\nconst sheet2_url = \'https://docs.google.com/spreadsheets/d/e/2PACX-1vR9j5cnQbY_wkcNGH9M6xW2o4wnSZdrmuEWdEDkZoZr-9dCTctjJ_h1N8SAS05sVRzrenCCnA8jJApz/pub?output=csv\';\n\nlet rawData = { sheet1: [], sheet2: [] };\n\n// Helper to fetch and parse\nconst parseCSV = (url) => new Promise((resolve) => {\n    Papa.parse(url, { download: true, header: true, complete: (results) => resolve(results.data) });\n});\n\n// Initialize\n(async () => {\n    rawData.sheet1 = await parseCSV(sheet1_url);\n    rawData.sheet2 = (await parseCSV(sheet2_url))[0];\n    \n    // Populate Continents\n    const contSelect = document.getElementById(\'continentSelect\');\n    const continents = [...new Set(rawData.sheet1.map(item => item.continent_id).filter(Boolean))];\n    continents.forEach(cont => {\n        let opt = document.createElement(\'option\');\n        opt.value = cont; opt.innerHTML = cont;\n        contSelect.appendChild(opt);\n    });\n})();\n\nfunction updateCountryDropdown() {\n    const cont = document.getElementById(\'continentSelect\').value;\n    const countrySelect = document.getElementById(\'countrySelect\');\n    countrySelect.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n    \n    rawData.sheet1.filter(c => c.continent_id === cont).forEach(c => {\n        let opt = document.createElement(\'option\');\n        opt.value = c.display_name; opt.innerHTML = c.display_name;\n        countrySelect.appendChild(opt);\n    });\n}\n\nfunction runCalc() {\n    const country = rawData.sheet1.find(c => c.display_name === document.getElementById(\'countrySelect\').value);\n    if (!country) return alert(\'Please select a country\');\n    \n    const build = rawData.sheet2;\n    const vol = parseFloat(document.getElementById(\'monthlyVolume\').value);\n    \n    let html = \'<table border=\"1\" style=\"width:100%; border-collapse:collapse; text-align:center; color:white; border-color:#333;\">\';\n    html += \'<tr style=\"background:#1a2b45;\"><th>Year</th><th>Human Cost</th><th>AI Cost</th><th>Savings</th></tr>\';\n    \n    for (let y = 1; y <= 5; y++) {\n        let humanCost = (parseFloat(country.avg_salary) + parseFloat(country.operating_cost)) * 12 * Math.pow(1 + parseFloat(country.avg_increase)/100, y - 1);\n        let aiTotal = parseFloat(build[`year_${y}_retainer`]) + ((parseFloat(build.voice_per_query) + parseFloat(build.llm_per_query)) * vol * 12) + (y === 1 ? parseFloat(build.initial_cost) : 0);\n        html += `<tr><td>${y}</td><td>$${humanCost.toFixed(0)}</td><td>$${aiTotal.toFixed(0)}</td><td>$${(humanCost - aiTotal).toFixed(0)}</td></tr>`;\n    }\n    document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n}\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 06:55:53','2026-06-29 06:55:53','',615,'http://lycos-core.local/?p=631',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (632,1,'2026-06-29 07:01:07','2026-06-29 07:01:07','[ux_html]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.3.2/papaparse.min.js\"></script>\n\n<div id=\"calc-ui\" style=\"color: white; padding: 20px; font-family: sans-serif;\">\n    <h3 style=\"color:#CAFF00;\">ROI Calculator</h3>\n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" onchange=\"updateCountryDropdown()\" style=\"width:100%; color:black; padding:5px; margin-bottom:15px;\">\n        <option value=\"\">-- Select Continent --</option>\n    </select>\n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:5px; margin-bottom:15px;\">\n        <option value=\"\">-- Select Country --</option>\n    </select>\n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; color:black; padding:5px; margin-bottom:15px;\">\n    <button onclick=\"runCalc()\" style=\"cursor:pointer; background:#CAFF00; border:none; padding:10px 20px; font-weight:bold; color:black; width:100%;\">CALCULATE ROI</button>\n    <div id=\"resultsTable\" style=\"margin-top:20px; overflow-x:auto;\"></div>\n</div>\n\n<script>\n// SWAPPED: Sheet 1 is now the Country/Continent Data\nconst sheet1_url = \'https://docs.google.com/spreadsheets/d/e/2PACX-1vQXuD8yBuovR32Qx_MvqpHAxx_Lq8uSPOOSkJ1ihtdsMs9FNIdaJKzaAIYifgocJXVQt30949WZcxzn/pub?output=csv\';\n// SWAPPED: Sheet 2 is now the Build/Retainer Data\nconst sheet2_url = \'https://docs.google.com/spreadsheets/d/e/2PACX-1vR9j5cnQbY_wkcNGH9M6xW2o4wnSZdrmuEWdEDkZoZr-9dCTctjJ_h1N8SAS05sVRzrenCCnA8jJApz/pub?output=csv\';\n\nlet rawData = { sheet1: [], sheet2: [] };\n\nasync function init() {\n    try {\n        const res1 = await fetch(sheet1_url);\n        const text1 = await res1.text();\n        rawData.sheet1 = Papa.parse(text1, { header: true }).data;\n\n        const res2 = await fetch(sheet2_url);\n        const text2 = await res2.text();\n        rawData.sheet2 = Papa.parse(text2, { header: true }).data[0];\n\n        // Populate Continents\n        const contSelect = document.getElementById(\'continentSelect\');\n        const continents = [...new Set(rawData.sheet1.map(item => item.continent_id).filter(Boolean))];\n        continents.forEach(cont => {\n            let opt = document.createElement(\'option\');\n            opt.value = cont; opt.innerHTML = cont;\n            contSelect.appendChild(opt);\n        });\n    } catch (e) {\n        console.error(\"Fetch failed:\", e);\n    }\n}\ninit();\n\nfunction updateCountryDropdown() {\n    const cont = document.getElementById(\'continentSelect\').value;\n    const countrySelect = document.getElementById(\'countrySelect\');\n    countrySelect.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n    rawData.sheet1.filter(c => c.continent_id === cont).forEach(c => {\n        let opt = document.createElement(\'option\');\n        opt.value = c.display_name; opt.innerHTML = c.display_name;\n        countrySelect.appendChild(opt);\n    });\n}\n\nfunction runCalc() {\n    const country = rawData.sheet1.find(c => c.display_name === document.getElementById(\'countrySelect\').value);\n    if (!country) return alert(\'Please select a country\');\n    const build = rawData.sheet2;\n    const vol = parseFloat(document.getElementById(\'monthlyVolume\').value);\n    \n    let html = \'<table border=\"1\" style=\"width:100%; border-collapse:collapse; text-align:center; color:white; border-color:#333;\">\';\n    html += \'<tr style=\"background:#1a2b45;\"><th>Year</th><th>Human Cost</th><th>AI Cost</th><th>Savings</th></tr>\';\n    for (let y = 1; y <= 5; y++) {\n        let humanCost = (parseFloat(country.avg_salary) + parseFloat(country.operating_cost)) * 12 * Math.pow(1 + parseFloat(country.avg_increase)/100, y - 1);\n        let aiTotal = parseFloat(build[`year_${y}_retainer`]) + ((parseFloat(build.voice_per_query) + parseFloat(build.llm_per_query)) * vol * 12) + (y === 1 ? parseFloat(build.initial_cost) : 0);\n        html += `<tr><td>${y}</td><td>$${humanCost.toFixed(0)}</td><td>$${aiTotal.toFixed(0)}</td><td>$${(humanCost - aiTotal).toFixed(0)}</td></tr>`;\n    }\n    document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n}\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 07:01:07','2026-06-29 07:01:07','',615,'http://lycos-core.local/?p=632',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (633,1,'2026-06-29 07:09:22','2026-06-29 07:09:22','[ux_html]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.3.2/papaparse.min.js\"></script>\n\n<div id=\"calc-ui\" style=\"color:white; font-family:sans-serif; padding:20px; background:#1a2b45; border-radius:8px;\">\n    <h3 style=\"color:#CAFF00;\">ROI Calculator</h3>\n    \n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" onchange=\"updateCountryDropdown()\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Continent --</option>\n    </select>\n    \n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Country --</option>\n    </select>\n    \n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; padding:8px; margin-bottom:15px; border-radius:4px;\">\n    \n    <button onclick=\"runCalc()\" style=\"background:#CAFF00; border:none; padding:12px; font-weight:bold; width:100%; cursor:pointer; border-radius:4px;\">CALCULATE SAVINGS</button>\n    \n    <div id=\"resultsTable\" style=\"margin-top:20px; overflow-x:auto;\"></div>\n</div>\n\n<script>\nconst BASE_URL = \'https://script.google.com/macros/s/AKfycbwGotFV7IHRG9PsjT6mFE9tmq3JSCkliZoLNTbhhp188AvfgTdN9aJy99xsyPug3XQ05w/exec\';\nlet rawData = { sheet1: [], sheet2: [] };\n\nasync function init() {\n    try {\n        // Fetch Sheet 1 (Costs)\n        const res1 = await fetch(BASE_URL + \'?sheet=1\');\n        const text1 = await res1.text();\n        rawData.sheet1 = Papa.parse(text1, { header: true }).data;\n\n        // Fetch Sheet 2 (Build/Retainer)\n        const res2 = await fetch(BASE_URL + \'?sheet=2\');\n        const text2 = await res2.text();\n        rawData.sheet2 = Papa.parse(text2, { header: true }).data[0];\n\n        // Populate Continent Dropdown\n        const select = document.getElementById(\'continentSelect\');\n        const continents = [...new Set(rawData.sheet1.map(i => i.continent_id).filter(Boolean))];\n        continents.forEach(c => select.innerHTML += `<option value=\"${c}\">${c}</option>`);\n    } catch (e) {\n        console.error(\"Data Load Error:\", e);\n        document.getElementById(\'calc-ui\').innerHTML = \"<p style=\'color:red;\'>Error loading data. Please check Apps Script deployment.</p>\";\n    }\n}\ninit();\n\nfunction updateCountryDropdown() {\n    const cont = document.getElementById(\'continentSelect\').value;\n    const countrySelect = document.getElementById(\'countrySelect\');\n    countrySelect.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n    rawData.sheet1.filter(c => c.continent_id === cont).forEach(c => {\n        countrySelect.innerHTML += `<option value=\"${c.display_name}\">${c.display_name}</option>`;\n    });\n}\n\nfunction runCalc() {\n    const country = rawData.sheet1.find(c => c.display_name === document.getElementById(\'countrySelect\').value);\n    if (!country) return alert(\'Please select a country first\');\n    \n    const b = rawData.sheet2;\n    const vol = parseFloat(document.getElementById(\'monthlyVolume\').value);\n    \n    let html = \'<table border=\"1\" style=\"width:100%; border-collapse:collapse; color:white; border-color:#555; text-align:center;\">\';\n    html += \'<tr style=\"background:#000;\"><th>Year</th><th>Human Cost</th><th>AI Total</th><th>Net Savings</th></tr>\';\n    \n    for (let y = 1; y <= 5; y++) {\n        let h = (parseFloat(country.avg_salary) + parseFloat(country.operating_cost)) * 12 * Math.pow(1 + parseFloat(country.avg_increase)/100, y-1);\n        let a = parseFloat(b[\'year_\'+y+\'_retainer\']) + ((parseFloat(b.voice_per_query)+parseFloat(b.llm_per_query)) * vol * 12) + (y==1 ? parseFloat(b.initial_cost) : 0);\n        html += `<tr><td>${y}</td><td>$${h.toFixed(0)}</td><td>$${a.toFixed(0)}</td><td>$${(h-a).toFixed(0)}</td></tr>`;\n    }\n    document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n}\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 07:09:22','2026-06-29 07:09:22','',615,'http://lycos-core.local/?p=633',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (634,1,'2026-06-29 07:09:22','2026-06-29 07:09:22','[ux_html]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.3.2/papaparse.min.js\"></script>\n\n<div id=\"calc-ui\" style=\"color:white; font-family:sans-serif; padding:20px; background:#1a2b45; border-radius:8px;\">\n    <h3 style=\"color:#CAFF00;\">ROI Calculator</h3>\n    \n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" onchange=\"updateCountryDropdown()\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Continent --</option>\n    </select>\n    \n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Country --</option>\n    </select>\n    \n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; padding:8px; margin-bottom:15px; border-radius:4px;\">\n    \n    <button onclick=\"runCalc()\" style=\"background:#CAFF00; border:none; padding:12px; font-weight:bold; width:100%; cursor:pointer; border-radius:4px;\">CALCULATE SAVINGS</button>\n    \n    <div id=\"resultsTable\" style=\"margin-top:20px; overflow-x:auto;\"></div>\n</div>\n\n<script>\nconst BASE_URL = \'https://script.google.com/macros/s/AKfycbwGotFV7IHRG9PsjT6mFE9tmq3JSCkliZoLNTbhhp188AvfgTdN9aJy99xsyPug3XQ05w/exec\';\nlet rawData = { sheet1: [], sheet2: [] };\n\nasync function init() {\n    try {\n        // Fetch Sheet 1 (Costs)\n        const res1 = await fetch(BASE_URL + \'?sheet=1\');\n        const text1 = await res1.text();\n        rawData.sheet1 = Papa.parse(text1, { header: true }).data;\n\n        // Fetch Sheet 2 (Build/Retainer)\n        const res2 = await fetch(BASE_URL + \'?sheet=2\');\n        const text2 = await res2.text();\n        rawData.sheet2 = Papa.parse(text2, { header: true }).data[0];\n\n        // Populate Continent Dropdown\n        const select = document.getElementById(\'continentSelect\');\n        const continents = [...new Set(rawData.sheet1.map(i => i.continent_id).filter(Boolean))];\n        continents.forEach(c => select.innerHTML += `<option value=\"${c}\">${c}</option>`);\n    } catch (e) {\n        console.error(\"Data Load Error:\", e);\n        document.getElementById(\'calc-ui\').innerHTML = \"<p style=\'color:red;\'>Error loading data. Please check Apps Script deployment.</p>\";\n    }\n}\ninit();\n\nfunction updateCountryDropdown() {\n    const cont = document.getElementById(\'continentSelect\').value;\n    const countrySelect = document.getElementById(\'countrySelect\');\n    countrySelect.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n    rawData.sheet1.filter(c => c.continent_id === cont).forEach(c => {\n        countrySelect.innerHTML += `<option value=\"${c.display_name}\">${c.display_name}</option>`;\n    });\n}\n\nfunction runCalc() {\n    const country = rawData.sheet1.find(c => c.display_name === document.getElementById(\'countrySelect\').value);\n    if (!country) return alert(\'Please select a country first\');\n    \n    const b = rawData.sheet2;\n    const vol = parseFloat(document.getElementById(\'monthlyVolume\').value);\n    \n    let html = \'<table border=\"1\" style=\"width:100%; border-collapse:collapse; color:white; border-color:#555; text-align:center;\">\';\n    html += \'<tr style=\"background:#000;\"><th>Year</th><th>Human Cost</th><th>AI Total</th><th>Net Savings</th></tr>\';\n    \n    for (let y = 1; y <= 5; y++) {\n        let h = (parseFloat(country.avg_salary) + parseFloat(country.operating_cost)) * 12 * Math.pow(1 + parseFloat(country.avg_increase)/100, y-1);\n        let a = parseFloat(b[\'year_\'+y+\'_retainer\']) + ((parseFloat(b.voice_per_query)+parseFloat(b.llm_per_query)) * vol * 12) + (y==1 ? parseFloat(b.initial_cost) : 0);\n        html += `<tr><td>${y}</td><td>$${h.toFixed(0)}</td><td>$${a.toFixed(0)}</td><td>$${(h-a).toFixed(0)}</td></tr>`;\n    }\n    document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n}\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 07:09:22','2026-06-29 07:09:22','',615,'http://lycos-core.local/?p=634',0,'revision','',0);
