INSERT INTO `wp_posts` VALUES (637,1,'2026-06-29 07:23:12','2026-06-29 07:23:12','[ux_html]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.3.2/papaparse.min.js\"></script>\n\n<div id=\"calc-ui\" style=\"color:white; font-family:sans-serif; padding:20px; background:#1a2b45; border-radius:8px;\">\n    <h3 style=\"color:#CAFF00;\">ROI Calculator</h3>\n    \n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" onchange=\"updateCountryDropdown()\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Continent --</option>\n    </select>\n    \n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Country --</option>\n    </select>\n    \n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; padding:8px; margin-bottom:15px; border-radius:4px;\">\n    \n    <button onclick=\"runCalc()\" style=\"background:#CAFF00; border:none; padding:12px; font-weight:bold; width:100%; cursor:pointer; border-radius:4px;\">CALCULATE SAVINGS</button>\n    \n    <div id=\"resultsTable\" style=\"margin-top:20px; overflow-x:auto;\"></div>\n</div>\n\n<script>\n// Correctly assigned based on your file naming\nconst url_costs = \'http://lycos-core.local/media/Lycos-Core-call-centre-costs-Sheet1.csv\';\nconst url_build = \'http://lycos-core.local/media/Lycos-Core-call-centre-build-cost-Sheet1.csv\';\n\nlet rawData = { costs: [], build: {} };\n\nasync function init() {\n    // Load Costs (Dropdown Data)\n    Papa.parse(url_costs, { download: true, header: true, complete: (res) => {\n        rawData.costs = res.data;\n        const conts = [...new Set(rawData.costs.map(i => i.continent_id).filter(Boolean))];\n        const sel = document.getElementById(\'continentSelect\');\n        conts.forEach(c => sel.innerHTML += `<option value=\"${c}\">${c}</option>`);\n    }});\n\n    // Load Build Data (Math Variables)\n    Papa.parse(url_build, { download: true, header: true, complete: (res) => {\n        rawData.build = res.data[0];\n    }});\n}\ninit();\n\nfunction updateCountryDropdown() {\n    const cont = document.getElementById(\'continentSelect\').value;\n    const sel = document.getElementById(\'countrySelect\');\n    sel.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n    rawData.costs.filter(c => c.continent_id === cont).forEach(c => {\n        sel.innerHTML += `<option value=\"${c.display_name}\">${c.display_name}</option>`;\n    });\n}\n\nfunction runCalc() {\n    const country = rawData.costs.find(c => c.display_name === document.getElementById(\'countrySelect\').value);\n    const b = rawData.build;\n    if (!country) return alert(\'Please select a country first\');\n    \n    const vol = parseFloat(document.getElementById(\'monthlyVolume\').value);\n    \n    let html = \'<table border=\"1\" style=\"width:100%; border-collapse:collapse; color:white; border-color:#555; text-align:center;\">\';\n    html += \'<tr style=\"background:#000;\"><th>Year</th><th>Human Cost</th><th>AI Total</th><th>Savings</th></tr>\';\n    \n    for (let y = 1; y <= 5; y++) {\n        let h = (parseFloat(country.avg_salary) + parseFloat(country.operating_cost)) * 12 * Math.pow(1 + parseFloat(country.avg_increase)/100, y-1);\n        let a = parseFloat(b[\'year_\'+y+\'_retainer\']) + ((parseFloat(b.voice_per_query) + parseFloat(b.llm_per_query)) * vol * 12) + (y==1 ? parseFloat(b.initial_cost) : 0);\n        html += `<tr><td>${y}</td><td>$${h.toFixed(0)}</td><td>$${a.toFixed(0)}</td><td>$${(h-a).toFixed(0)}</td></tr>`;\n    }\n    document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n}\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 07:23:12','2026-06-29 07:23:12','',615,'http://lycos-core.local/?p=637',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (638,1,'2026-06-29 07:25:59','2026-06-29 07:25:59','[ux_html]\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/PapaParse/5.3.2/papaparse.min.js\"></script>\n\n<div id=\"calc-ui\" style=\"color:white; font-family:sans-serif; padding:20px; background:#1a2b45; border-radius:8px;\">\n    <h3 style=\"color:#CAFF00;\">ROI Calculator</h3>\n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" onchange=\"updateCountryDropdown()\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px;\"></select>\n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px;\"></select>\n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; padding:8px; margin-bottom:15px; color:black;\">\n    <button id=\"calcBtn\" style=\"background:#CAFF00; border:none; padding:12px; font-weight:bold; width:100%; cursor:pointer;\">CALCULATE SAVINGS</button>\n    <div id=\"resultsTable\" style=\"margin-top:20px;\"></div>\n</div>\n\n<script>\nwindow.addEventListener(\'load\', function() {\n    const url_costs = \'http://lycos-core.local/media/Lycos-Core-call-centre-costs-Sheet1.csv\';\n    const url_build = \'http://lycos-core.local/media/Lycos-Core-call-centre-build-cost-Sheet1.csv\';\n    let rawData = { costs: [], build: {} };\n\n    // Load Data\n    Papa.parse(url_costs, { download: true, header: true, complete: (res) => {\n        rawData.costs = res.data;\n        const conts = [...new Set(rawData.costs.map(i => i.continent_id).filter(Boolean))];\n        const sel = document.getElementById(\'continentSelect\');\n        sel.innerHTML = \'<option value=\"\">-- Select Continent --</option>\';\n        conts.forEach(c => sel.innerHTML += `<option value=\"${c}\">${c}</option>`);\n    }});\n\n    Papa.parse(url_build, { download: true, header: true, complete: (res) => {\n        rawData.build = res.data[0];\n    }});\n\n    window.updateCountryDropdown = function() {\n        const cont = document.getElementById(\'continentSelect\').value;\n        const sel = document.getElementById(\'countrySelect\');\n        sel.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n        rawData.costs.filter(c => c.continent_id === cont).forEach(c => {\n            sel.innerHTML += `<option value=\"${c.display_name}\">${c.display_name}</option>`;\n        });\n    };\n\n    document.getElementById(\'calcBtn\').onclick = function() {\n        const country = rawData.costs.find(c => c.display_name === document.getElementById(\'countrySelect\').value);\n        if (!country) return alert(\'Please select a country\');\n        const b = rawData.build;\n        const vol = parseFloat(document.getElementById(\'monthlyVolume\').value);\n        let html = \'<table border=\"1\" style=\"width:100%; color:white; border-collapse:collapse; text-align:center;\"><tr><th>Year</th><th>Human</th><th>AI</th><th>Savings</th></tr>\';\n        for (let y = 1; y <= 5; y++) {\n            let h = (parseFloat(country.avg_salary) + parseFloat(country.operating_cost)) * 12 * Math.pow(1 + parseFloat(country.avg_increase)/100, y-1);\n            let a = parseFloat(b[\'year_\'+y+\'_retainer\']) + ((parseFloat(b.voice_per_query) + parseFloat(b.llm_per_query)) * vol * 12) + (y==1 ? parseFloat(b.initial_cost) : 0);\n            html += `<tr><td>${y}</td><td>$${h.toFixed(0)}</td><td>$${a.toFixed(0)}</td><td>$${(h-a).toFixed(0)}</td></tr>`;\n        }\n        document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n    };\n});\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 07:25:59','2026-06-29 07:25:59','',615,'http://lycos-core.local/?p=638',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (639,1,'2026-06-29 07:29:20','2026-06-29 07:29:20','[ux_html]\n\n<div id=\"calc-ui\" style=\"color:white; font-family:sans-serif; padding:20px; background:#1a2b45; border-radius:8px;\">\n    <h3 style=\"color:#CAFF00;\">ROI Calculator</h3>\n    \n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" onchange=\"updateCountryDropdown()\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Continent --</option>\n    </select>\n    \n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Country --</option>\n    </select>\n    \n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; padding:8px; margin-bottom:15px; border-radius:4px; color:black;\">\n    \n    <button id=\"calcBtn\" style=\"background:#CAFF00; border:none; padding:12px; font-weight:bold; width:100%; cursor:pointer; border-radius:4px; color:black;\">CALCULATE SAVINGS</button>\n    \n    <div id=\"resultsTable\" style=\"margin-top:20px; overflow-x:auto;\"></div>\n</div>\n\n<script>\n// Static data embedded directly to avoid loading/CORS/path issues\nconst countryData = [\n    { continent: \"Africa\", name: \"Ghana\", salary: 215, cost: 350, increase: 11 },\n    { continent: \"Africa\", name: \"Mozambique\", salary: 400, cost: 450, increase: 7 },\n    { continent: \"Africa\", name: \"South Africa\", salary: 615, cost: 250, increase: 6 },\n    { continent: \"Africa\", name: \"Botswana\", salary: 405, cost: 280, increase: 7 },\n    { continent: \"Africa\", name: \"Zambia\", salary: 210, cost: 320, increase: 14 },\n    { continent: \"Africa\", name: \"Uganda\", salary: 350, cost: 290, increase: 8 },\n    { continent: \"Africa\", name: \"Kenya\", salary: 405, cost: 230, increase: 9 },\n    { continent: \"Africa\", name: \"Tanzania\", salary: 400, cost: 270, increase: 9 },\n    { continent: \"Africa\", name: \"Seychelles\", salary: 915, cost: 450, increase: 8 },\n    { continent: \"Africa\", name: \"Mauritius\", salary: 625, cost: 220, increase: 5 },\n    { continent: \"Africa\", name: \"Nigeria\", salary: 102, cost: 310, increase: 24 },\n    { continent: \"Oceania\", name: \"New Zealand\", salary: 3145, cost: 550, increase: 5 },\n    { continent: \"Oceania\", name: \"Australia\", salary: 3540, cost: 680, increase: 4 }\n];\n\nconst build = {\n    initial: 5000, \n    y1: 1000, y2: 1100, y3: 1210, y4: 1331, y5: 1464,\n    voice: 0.05, llm: 0.02\n};\n\n// Initialize\nconst contSel = document.getElementById(\'continentSelect\');\nconst continents = [...new Set(countryData.map(c => c.continent))];\ncontinents.forEach(c => contSel.innerHTML += `<option value=\"${c}\">${c}</option>`);\n\nfunction updateCountryDropdown() {\n    const cont = contSel.value;\n    const countrySel = document.getElementById(\'countrySelect\');\n    countrySel.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n    countryData.filter(c => c.continent === cont).forEach(c => {\n        countrySel.innerHTML += `<option value=\"${c.name}\">${c.name}</option>`;\n    });\n}\n\ndocument.getElementById(\'calcBtn\').onclick = function() {\n    const country = countryData.find(c => c.name === document.getElementById(\'countrySelect\').value);\n    if (!country) return alert(\'Please select a country\');\n    const vol = parseFloat(document.getElementById(\'monthlyVolume\').value);\n    \n    let html = \'<table border=\"1\" style=\"width:100%; color:white; border-collapse:collapse; text-align:center;\">\';\n    html += \'<tr style=\"background:#000;\"><th>Year</th><th>Human</th><th>AI</th><th>Savings</th></tr>\';\n    \n    for (let y = 1; y <= 5; y++) {\n        let h = (country.salary + country.cost) * 12 * Math.pow(1 + country.increase/100, y-1);\n        let a = build[\'y\'+y] + ((build.voice + build.llm) * vol * 12) + (y==1 ? build.initial : 0);\n        html += `<tr><td>${y}</td><td>$${h.toFixed(0)}</td><td>$${a.toFixed(0)}</td><td>$${(h-a).toFixed(0)}</td></tr>`;\n    }\n    document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n};\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 07:29:20','2026-06-29 07:29:20','',615,'http://lycos-core.local/?p=639',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (640,1,'2026-06-29 07:33:55','2026-06-29 07:33:55','[ux_html]\n\n<div id=\"calc-ui\" style=\"color:white; font-family:sans-serif; padding:20px; background:#1a2b45; border-radius:8px;\">\n    <h3 style=\"color:#CAFF00;\">ROI Calculator</h3>\n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Continent --</option>\n    </select>\n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Country --</option>\n    </select>\n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; padding:8px; margin-bottom:15px; border-radius:4px; color:black;\">\n    <button id=\"calcBtn\" style=\"background:#CAFF00; border:none; padding:12px; font-weight:bold; width:100%; cursor:pointer; border-radius:4px; color:black;\">CALCULATE SAVINGS</button>\n    <div id=\"resultsTable\" style=\"margin-top:20px; overflow-x:auto;\"></div>\n</div>\n\n<script>\n(function() {\n    const countryData = [\n        { continent: \"Africa\", name: \"Ghana\", salary: 215, cost: 350, increase: 11 },\n        { continent: \"Africa\", name: \"Mozambique\", salary: 400, cost: 450, increase: 7 },\n        { continent: \"Africa\", name: \"South Africa\", salary: 615, cost: 250, increase: 6 },\n        { continent: \"Oceania\", name: \"New Zealand\", salary: 3145, cost: 550, increase: 5 },\n        { continent: \"Oceania\", name: \"Australia\", salary: 3540, cost: 680, increase: 4 }\n    ];\n\n    const build = { initial: 5000, y1: 1000, y2: 1100, y3: 1210, y4: 1331, y5: 1464, voice: 0.05, llm: 0.02 };\n\n    const initCalc = () => {\n        const contSel = document.getElementById(\'continentSelect\');\n        const countrySel = document.getElementById(\'countrySelect\');\n        const continents = [...new Set(countryData.map(c => c.continent))];\n        \n        continents.forEach(c => contSel.innerHTML += `<option value=\"${c}\">${c}</option>`);\n\n        contSel.addEventListener(\'change\', function() {\n            countrySel.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n            countryData.filter(c => c.continent === this.value).forEach(c => {\n                countrySel.innerHTML += `<option value=\"${c.name}\">${c.name}</option>`;\n            });\n        });\n\n        document.getElementById(\'calcBtn\').addEventListener(\'click\', function() {\n            const country = countryData.find(c => c.name === countrySel.value);\n            if (!country) return alert(\'Please select a country\');\n            const vol = parseFloat(document.getElementById(\'monthlyVolume\').value);\n            let html = \'<table border=\"1\" style=\"width:100%; color:white; border-collapse:collapse; text-align:center;\"><tr style=\"background:#000;\"><th>Year</th><th>Human</th><th>AI</th><th>Savings</th></tr>\';\n            for (let y = 1; y <= 5; y++) {\n                let h = (country.salary + country.cost) * 12 * Math.pow(1 + country.increase/100, y-1);\n                let a = build[\'y\'+y] + ((build.voice + build.llm) * vol * 12) + (y==1 ? build.initial : 0);\n                html += `<tr><td>${y}</td><td>$${h.toFixed(0)}</td><td>$${a.toFixed(0)}</td><td>$${(h-a).toFixed(0)}</td></tr>`;\n            }\n            document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n        });\n    };\n\n    if (document.readyState === \'loading\') {\n        document.addEventListener(\'DOMContentLoaded\', initCalc);\n    } else {\n        initCalc();\n    }\n})();\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 07:33:55','2026-06-29 07:33:55','',615,'http://lycos-core.local/?p=640',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (641,1,'2026-06-29 07:36:45','2026-06-29 07:36:45','[ux_html]\n\n<div id=\"calc-ui\" style=\"color:white; font-family:sans-serif; padding:20px; background:#1a2b45; border-radius:8px;\">\n    <h3 style=\"color:#CAFF00;\">ROI Calculator</h3>\n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Continent --</option>\n    </select>\n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Country --</option>\n    </select>\n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; padding:8px; margin-bottom:15px; color:black; border-radius:4px;\">\n    <button id=\"calcBtn\" style=\"background:#CAFF00; border:none; padding:12px; font-weight:bold; width:100%; cursor:pointer; color:black; border-radius:4px;\">CALCULATE SAVINGS</button>\n    <div id=\"resultsTable\" style=\"margin-top:20px; overflow-x:auto;\"></div>\n</div>\n\n<script>\n(function() {\n    // 1. DATA (Keep this up to date here)\n    const countryData = [\n        { continent: \"Africa\", name: \"Ghana\", salary: 215, cost: 350, increase: 11 },\n        { continent: \"Africa\", name: \"Mozambique\", salary: 400, cost: 450, increase: 7 },\n        { continent: \"Africa\", name: \"South Africa\", salary: 615, cost: 250, increase: 6 },\n        { continent: \"Oceania\", name: \"New Zealand\", salary: 3145, cost: 550, increase: 5 },\n        { continent: \"Oceania\", name: \"Australia\", salary: 3540, cost: 680, increase: 4 }\n    ];\n    const build = { initial: 5000, y1: 1000, y2: 1100, y3: 1210, y4: 1331, y5: 1464, voice: 0.05, llm: 0.02 };\n\n    // 2. INITIALIZATION\n    function init() {\n        const contSel = document.getElementById(\'continentSelect\');\n        const countrySel = document.getElementById(\'countrySelect\');\n        const calcBtn = document.getElementById(\'calcBtn\');\n        \n        // Populate Continents\n        const continents = [...new Set(countryData.map(c => c.continent))];\n        contSel.innerHTML = \'<option value=\"\">-- Select Continent --</option>\';\n        continents.forEach(c => contSel.innerHTML += `<option value=\"${c}\">${c}</option>`);\n\n        // Country Logic\n        contSel.onchange = function() {\n            countrySel.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n            countryData.filter(c => c.continent === this.value).forEach(c => {\n                countrySel.innerHTML += `<option value=\"${c.name}\">${c.name}</option>`;\n            });\n        };\n\n        // Calculation Logic\n        calcBtn.onclick = function() {\n            const country = countryData.find(c => c.name === countrySel.value);\n            if (!country) return alert(\'Please select a country\');\n            const vol = parseFloat(document.getElementById(\'monthlyVolume\').value);\n            let html = \'<table border=\"1\" style=\"width:100%; color:white; border-collapse:collapse; text-align:center;\"><tr style=\"background:#000;\"><th>Year</th><th>Human</th><th>AI</th><th>Savings</th></tr>\';\n            for (let y = 1; y <= 5; y++) {\n                let h = (country.salary + country.cost) * 12 * Math.pow(1 + country.increase/100, y-1);\n                let a = build[\'y\'+y] + ((build.voice + build.llm) * vol * 12) + (y==1 ? build.initial : 0);\n                html += `<tr><td>${y}</td><td>$${h.toFixed(0)}</td><td>$${a.toFixed(0)}</td><td>$${(h-a).toFixed(0)}</td></tr>`;\n            }\n            document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n        };\n    }\n\n    // 3. WAIT FOR POPUP TO BE VISIBLE (The \"Theme-Proof\" part)\n    const observer = new MutationObserver((mutations, obs) => {\n        if (document.getElementById(\'continentSelect\')) {\n            init();\n            obs.disconnect();\n        }\n    });\n    observer.observe(document.body, { childList: true, subtree: true });\n})();\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 07:36:45','2026-06-29 07:36:45','',615,'http://lycos-core.local/?p=641',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (642,1,'2026-06-29 07:39:20','2026-06-29 07:39:20','[ux_html]\n\n<div id=\"calc-ui\" style=\"color:white; font-family:sans-serif; padding:20px; background:#1a2b45; border-radius:8px;\">\n    <h3 style=\"color:#CAFF00;\">ROI Calculator</h3>\n    <label>Select Continent:</label><br>\n    <select id=\"continentSelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Continent --</option>\n    </select>\n    <label>Select Country:</label><br>\n    <select id=\"countrySelect\" style=\"width:100%; color:black; padding:8px; margin-bottom:15px; border-radius:4px;\">\n        <option value=\"\">-- Select Country --</option>\n    </select>\n    <label>Monthly Call Volume:</label><br>\n    <input type=\"number\" id=\"monthlyVolume\" value=\"1000\" style=\"width:100%; padding:8px; margin-bottom:15px; color:black; border-radius:4px;\">\n    <button id=\"calcBtn\" style=\"background:#CAFF00; border:none; padding:12px; font-weight:bold; width:100%; cursor:pointer; color:black; border-radius:4px;\">CALCULATE SAVINGS</button>\n    <div id=\"resultsTable\" style=\"margin-top:20px; overflow-x:auto;\"></div>\n</div>\n\n<script>\n(function() {\n    // 1. DATA (Keep this up to date here)\n    const countryData = [\n        { continent: \"Africa\", name: \"Ghana\", salary: 215, cost: 350, increase: 11 },\n        { continent: \"Africa\", name: \"Mozambique\", salary: 400, cost: 450, increase: 7 },\n        { continent: \"Africa\", name: \"South Africa\", salary: 615, cost: 250, increase: 6 },\n        { continent: \"Oceania\", name: \"New Zealand\", salary: 3145, cost: 550, increase: 5 },\n        { continent: \"Oceania\", name: \"Australia\", salary: 3540, cost: 680, increase: 4 }\n    ];\n    const build = { initial: 5000, y1: 1000, y2: 1100, y3: 1210, y4: 1331, y5: 1464, voice: 0.05, llm: 0.02 };\n\n    // 2. INITIALIZATION\n    function init() {\n        const contSel = document.getElementById(\'continentSelect\');\n        const countrySel = document.getElementById(\'countrySelect\');\n        const calcBtn = document.getElementById(\'calcBtn\');\n        \n        // Populate Continents\n        const continents = [...new Set(countryData.map(c => c.continent))];\n        contSel.innerHTML = \'<option value=\"\">-- Select Continent --</option>\';\n        continents.forEach(c => contSel.innerHTML += `<option value=\"${c}\">${c}</option>`);\n\n        // Country Logic\n        contSel.onchange = function() {\n            countrySel.innerHTML = \'<option value=\"\">-- Select Country --</option>\';\n            countryData.filter(c => c.continent === this.value).forEach(c => {\n                countrySel.innerHTML += `<option value=\"${c.name}\">${c.name}</option>`;\n            });\n        };\n\n        // Calculation Logic\n        calcBtn.onclick = function() {\n            const country = countryData.find(c => c.name === countrySel.value);\n            if (!country) return alert(\'Please select a country\');\n            const vol = parseFloat(document.getElementById(\'monthlyVolume\').value);\n            let html = \'<table border=\"1\" style=\"width:100%; color:white; border-collapse:collapse; text-align:center;\"><tr style=\"background:#000;\"><th>Year</th><th>Human</th><th>AI</th><th>Savings</th></tr>\';\n            for (let y = 1; y <= 5; y++) {\n                let h = (country.salary + country.cost) * 12 * Math.pow(1 + country.increase/100, y-1);\n                let a = build[\'y\'+y] + ((build.voice + build.llm) * vol * 12) + (y==1 ? build.initial : 0);\n                html += `<tr><td>${y}</td><td>$${h.toFixed(0)}</td><td>$${a.toFixed(0)}</td><td>$${(h-a).toFixed(0)}</td></tr>`;\n            }\n            document.getElementById(\'resultsTable\').innerHTML = html + \'</table>\';\n        };\n    }\n\n    // 3. THEME-PROOF OBSERVER\n    // This watches the body for the calculator elements. Once found, it runs init() and stops watching.\n    const observer = new MutationObserver((mutations, obs) => {\n        if (document.getElementById(\'continentSelect\')) {\n            init();\n            obs.disconnect();\n        }\n    });\n    observer.observe(document.body, { childList: true, subtree: true });\n})();\n</script>\n[/ux_html]','Call Centre','','inherit','closed','closed','','615-revision-v1','','','2026-06-29 07:39:20','2026-06-29 07:39:20','',615,'http://lycos-core.local/?p=642',0,'revision','',0);
